css:
@keyframes dhs-shift-rise { from { opacity: 0; translate: 0 8px; } }
@keyframes dhs-shift-grow { from { scale: 1 0; } }
@keyframes dhs-shift-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dhs-shift-pop { from { opacity: 0; scale: 0.2; } }
@keyframes dhs-shift-toast { 0% { opacity: 0; translate: -50% 12px; } 12%, 85% { opacity: 1; translate: -50% 0; } 100% { opacity: 0; translate: -50% 6px; } }

.dhs-shift {
  /* re-theme with these four */
  --dhs-shift-bg: oklch(0.19 0.012 60);
  --dhs-shift-ink: oklch(0.94 0.014 80);
  --dhs-shift-accent: oklch(0.83 0.15 80);
  --dhs-shift-hot: oklch(0.68 0.18 38);
  /* course hues, derived */
  --dhs-shift-starter: oklch(0.79 0.085 178);
  --dhs-shift-main: var(--dhs-shift-accent);
  --dhs-shift-dessert: oklch(0.76 0.1 350);
  --dhs-shift-card: color-mix(in oklch, var(--dhs-shift-bg), var(--dhs-shift-ink) 4.5%);
  --dhs-shift-raise: color-mix(in oklch, var(--dhs-shift-bg), var(--dhs-shift-ink) 10%);
  --dhs-shift-sunk: color-mix(in oklch, var(--dhs-shift-bg), black 25%);
  --dhs-shift-line: color-mix(in oklch, var(--dhs-shift-ink) 9%, transparent);
  --dhs-shift-line2: color-mix(in oklch, var(--dhs-shift-ink) 18%, transparent);
  --dhs-shift-muted: color-mix(in oklch, var(--dhs-shift-ink) 62%, var(--dhs-shift-bg));
  --dhs-shift-faint: color-mix(in oklch, var(--dhs-shift-ink) 40%, var(--dhs-shift-bg));
  --dhs-shift-ease: cubic-bezier(0.22, 0.9, 0.24, 1);
  --dhs-shift-spring: linear(0, 0.02, 0.09 4%, 0.48 12%, 0.88 19%, 1.06 26%, 1.09 31%, 1.05 38%, 0.99 49%, 1);
  --dhs-shift-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dhs-shift-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhs-shift-bg);
  color: var(--dhs-shift-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dhs-shift-accent);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dhs-shift-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  [data-c="starter"] { --cc: var(--dhs-shift-starter); }
  [data-c="main"] { --cc: var(--dhs-shift-main); }
  [data-c="dessert"] { --cc: var(--dhs-shift-dessert); }

  .dhs-shift-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dhs-shift-muted); }
  .dhs-shift-note { font-size: 11.5px; color: var(--dhs-shift-muted); font-variant-numeric: tabular-nums; }
  .dhs-shift-app { display: grid; height: 100%; grid-template-columns: 200px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dhs-shift-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px 14px; background: var(--dhs-shift-sunk); border-right: 1px solid var(--dhs-shift-line); scrollbar-width: thin; scrollbar-color: var(--dhs-shift-line2) transparent; }
  .dhs-shift-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
  .dhs-shift-brand svg { flex: none; width: 32px; height: 32px; padding: 6px; border-radius: 9px; background: color-mix(in oklch, var(--dhs-shift-accent) 16%, transparent); fill: none; stroke: var(--dhs-shift-accent); stroke-width: 1.8; stroke-linecap: round; }
  .dhs-shift-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dhs-shift-brand b { font-size: 14px; font-weight: 700; letter-spacing: -0.01em; }
  .dhs-shift-brand small { font-size: 11px; color: var(--dhs-shift-muted); }
  .dhs-shift-nav { display: grid; gap: 2px; }
  .dhs-shift-nav button { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--dhs-shift-muted); font-weight: 560; transition: background-color 160ms, color 160ms; }
  .dhs-shift-nav button:hover { color: var(--dhs-shift-ink); background: color-mix(in oklch, var(--dhs-shift-ink) 5%, transparent); }
  .dhs-shift-nav [aria-selected="true"] { color: var(--dhs-shift-ink); background: var(--dhs-shift-raise); box-shadow: inset 2px 0 0 var(--dhs-shift-accent); }
  .dhs-shift-nav svg { flex: none; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-shift-nav em { margin-left: auto; font: 600 10.5px var(--dhs-shift-mono); font-style: normal; color: var(--dhs-shift-faint); font-variant-numeric: tabular-nums; }
  .dhs-shift-days { display: grid; gap: 4px; }
  .dhs-shift-days .dhs-shift-eyebrow { padding: 0 6px 2px; }
  .dhs-shift-days button { display: grid; grid-template-columns: 34px 1fr auto; align-items: baseline; gap: 6px; padding: 7px 10px; border-radius: 9px; text-align: left; color: var(--dhs-shift-muted); box-shadow: inset 0 0 0 1px var(--dhs-shift-line); transition: background-color 160ms, color 160ms, box-shadow 160ms; }
  .dhs-shift-days button:hover { color: var(--dhs-shift-ink); box-shadow: inset 0 0 0 1px var(--dhs-shift-line2); }
  .dhs-shift-days [aria-checked="true"] { color: var(--dhs-shift-ink); background: color-mix(in oklch, var(--dhs-shift-accent) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dhs-shift-accent) 55%, transparent); }
  .dhs-shift-days b { font-weight: 700; }
  .dhs-shift-days small { font-size: 11.5px; }
  .dhs-shift-days em { font: 500 11px var(--dhs-shift-mono); font-style: normal; color: var(--dhs-shift-faint); font-variant-numeric: tabular-nums; }
  .dhs-shift-targets { display: grid; gap: 5px; margin-top: auto; padding: 12px 10px; border-radius: 10px; background: color-mix(in oklch, var(--dhs-shift-ink) 3%, transparent); }
  .dhs-shift-targets div { display: flex; justify-content: space-between; font-size: 12px; }
  .dhs-shift-targets dt { color: var(--dhs-shift-muted); }
  .dhs-shift-targets dd { font: 600 11.5px var(--dhs-shift-mono); font-variant-numeric: tabular-nums; }

  /* ---------- main ---------- */
  .dhs-shift-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }
  .dhs-shift-head { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 10px 22px; padding: 16px 18px 12px; }
  .dhs-shift-title { display: grid; gap: 3px; margin-right: auto; }
  .dhs-shift-title h2 { font-size: clamp(19px, 0.75rem + 1.25cqi, 26px); font-weight: 720; letter-spacing: -0.028em; line-height: 1.05; }
  .dhs-shift-clock { display: grid; justify-items: end; gap: 1px; }
  .dhs-shift-clock output { font: 650 clamp(22px, 0.9rem + 1.3cqi, 30px)/1 var(--dhs-shift-mono); letter-spacing: -0.04em; color: var(--dhs-shift-accent); font-variant-numeric: tabular-nums; }
  .dhs-shift-play { display: flex; gap: 6px; }
  .dhs-shift-btn { display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 13px 0 11px; border-radius: 10px; font-weight: 620; font-size: 12.5px; background: var(--dhs-shift-raise); box-shadow: inset 0 0 0 1px var(--dhs-shift-line2); transition: background-color 160ms, scale 240ms var(--dhs-shift-spring), opacity 160ms; }
  .dhs-shift-btn:hover { background: color-mix(in oklch, var(--dhs-shift-raise), var(--dhs-shift-ink) 7%); }
  .dhs-shift-btn:active { scale: 0.96; }
  .dhs-shift-btn:disabled { opacity: 0.38; cursor: not-allowed; scale: 1; }
  .dhs-shift-btn svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-shift-btn[data-act="play"] { background: var(--dhs-shift-accent); color: var(--dhs-shift-bg); box-shadow: none; }
  .dhs-shift-btn[data-act="play"]:hover { background: color-mix(in oklch, var(--dhs-shift-accent), white 14%); }
  .dhs-shift-btn[data-act="play"] svg { fill: currentColor; }
  .dhs-shift-ico-pause { display: none; }
  .dhs-shift-btn[aria-pressed="true"] .dhs-shift-ico-play { display: none; }
  .dhs-shift-btn[aria-pressed="true"] .dhs-shift-ico-pause { display: block; }

  .dhs-shift-kpis { display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); margin: 0 18px 12px; border-radius: 12px; background: var(--dhs-shift-card); box-shadow: inset 0 0 0 1px var(--dhs-shift-line); }
  .dhs-shift-kpis div { display: grid; align-content: start; gap: 1px; padding: 10px 12px 9px; min-width: 0; border-left: 1px solid var(--dhs-shift-line); }
  .dhs-shift-kpis div:first-child { border-left: 0; }
  .dhs-shift-kpis dt { font-size: 11px; font-weight: 560; color: var(--dhs-shift-muted); white-space: nowrap; }
  .dhs-shift-kpis dd { font-size: clamp(17px, 0.55rem + 1.1cqi, 22px); font-weight: 700; letter-spacing: -0.025em; line-height: 1.2; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dhs-shift-kpis dd[data-tone="hot"] { color: var(--dhs-shift-hot); }
  .dhs-shift-kpis dd[data-tone="ok"] { color: var(--dhs-shift-starter); }
  .dhs-shift-kpis small { font-size: 10.5px; color: var(--dhs-shift-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }

  .dhs-shift-pane { min-height: 0; padding: 0 18px 16px; }
  .dhs-shift-card { min-width: 0; border-radius: 13px; background: var(--dhs-shift-card); box-shadow: inset 0 0 0 1px var(--dhs-shift-line); padding: 12px 14px; }
  .dhs-shift-cardhead { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 12px; margin-bottom: 8px; }
  .dhs-shift-cardhead h3 { font-size: 12.5px; font-weight: 680; letter-spacing: -0.005em; }

  /* ---------- service ---------- */
  .dhs-shift-service { display: grid; grid-template-columns: minmax(0, 1fr) clamp(232px, 24cqi, 276px); grid-template-areas: "chart side"; gap: 12px; }
  .dhs-shift-chartcard { grid-area: chart; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; }
  .dhs-shift-legend { display: flex; flex-wrap: wrap; gap: 3px 12px; font-size: 11px; color: var(--dhs-shift-muted); }
  .dhs-shift-legend li { display: flex; align-items: center; gap: 5px; }
  .dhs-shift-legend li::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--cc); }
  .dhs-shift-legend [data-c="house"]::before { width: 12px; height: 8px; border-radius: 2px; background: color-mix(in oklch, var(--dhs-shift-ink) 22%, transparent); box-shadow: inset 0 1.5px 0 var(--dhs-shift-ink); }
  .dhs-shift-legend [data-c="seat"]::before { width: 5px; height: 10px; border-radius: 1px; background: color-mix(in oklch, var(--dhs-shift-accent) 55%, transparent); }
  .dhs-shift-chart { position: relative; min-height: 220px; cursor: ew-resize; touch-action: pan-y; border-radius: 8px; user-select: none; -webkit-user-select: none; }
  .dhs-shift-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dhs-shift-hint { margin-top: 6px; font-size: 11px; color: var(--dhs-shift-faint); }
  .dhs-shift-pill { position: absolute; top: -2px; left: 0; translate: -50% 0; padding: 2px 7px; border-radius: 99px; background: var(--dhs-shift-accent); color: var(--dhs-shift-bg); font: 700 10.5px/1.4 var(--dhs-shift-mono); font-variant-numeric: tabular-nums; pointer-events: none; box-shadow: 0 2px 10px oklch(0 0 0 / 0.4); }

  .dhs-shift-svg {
    .dhs-shift-grid line { stroke: var(--dhs-shift-line); shape-rendering: crispEdges; }
    .dhs-shift-grid text, .dhs-shift-ax text { fill: var(--dhs-shift-faint); font: 500 10px var(--dhs-shift-mono); font-variant-numeric: tabular-nums; }
    .dhs-shift-ax .dhs-shift-axlabel { fill: var(--dhs-shift-muted); font: 650 9.5px system-ui, sans-serif; letter-spacing: 0.08em; text-transform: uppercase; }
    .dhs-shift-cap { stroke: var(--dhs-shift-line2); stroke-dasharray: 3 4; }
    .dhs-shift-captext { fill: var(--dhs-shift-muted); font: 600 10px system-ui, sans-serif; }
    .dhs-shift-area { fill: color-mix(in oklch, var(--dhs-shift-ink) 13%, transparent); }
    .dhs-shift-areaLine { fill: none; stroke: var(--dhs-shift-ink); stroke-width: 1.6; stroke-linejoin: round; }
    .dhs-shift-col { fill: color-mix(in oklch, var(--dhs-shift-accent) 52%, transparent); transform-box: fill-box; transform-origin: 50% 100%; }
    .dhs-shift-target { stroke: var(--dhs-shift-hot); stroke-dasharray: 4 3; stroke-width: 1; opacity: 0.85; }
    .dhs-shift-targettext { fill: var(--dhs-shift-hot); font: 600 10px system-ui, sans-serif; }
    .dhs-shift-dot { fill: var(--cc); stroke: var(--dhs-shift-card); stroke-width: 1; transform-box: fill-box; transform-origin: center; transition: opacity 200ms, r 200ms var(--dhs-shift-spring); }
    .dhs-shift-dot[data-late] { stroke: var(--dhs-shift-hot); stroke-width: 1.6; }
    &[data-pick] .dhs-shift-dot { opacity: 0.22; }
    &[data-pick] .dhs-shift-dot[data-mine] { opacity: 1; r: 5.5px; stroke: var(--dhs-shift-ink); stroke-width: 1.6; }
    .dhs-shift-future { fill: color-mix(in oklch, var(--dhs-shift-card) 72%, transparent); }
    .dhs-shift-futurehatch { stroke: var(--dhs-shift-line); stroke-width: 1; }
    .dhs-shift-scrub { stroke: var(--dhs-shift-accent); stroke-width: 1.5; }
    .dhs-shift-hover { stroke: var(--dhs-shift-ink); stroke-opacity: 0.35; stroke-dasharray: 2 3; pointer-events: none; }
    .dhs-shift-panelsep { stroke: var(--dhs-shift-line2); }
  }
  &[data-enter] {
    .dhs-shift-col { animation: dhs-shift-grow 620ms var(--dhs-shift-ease) both; animation-delay: calc(var(--i) * 22ms); }
    .dhs-shift-houseg { animation: dhs-shift-wipe 1100ms var(--dhs-shift-ease) both; }
    .dhs-shift-dot { animation: dhs-shift-pop 420ms var(--dhs-shift-spring) both; animation-delay: calc(200ms + var(--i) * 26ms); }
  }

  .dhs-shift-sidecol { grid-area: side; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 12px; scrollbar-width: thin; scrollbar-color: var(--dhs-shift-line2) transparent; }
  .dhs-shift-meters { display: grid; gap: 9px; }
  .dhs-shift-meters li { display: grid; grid-template-columns: 1fr auto; gap: 3px 8px; font-size: 12px; }
  .dhs-shift-meters b { font: 650 12px var(--dhs-shift-mono); font-variant-numeric: tabular-nums; }
  .dhs-shift-meters li[data-over] b { color: var(--dhs-shift-hot); }
  .dhs-shift-meter { grid-column: 1 / -1; position: relative; height: 6px; border-radius: 3px; background: var(--dhs-shift-line); overflow: hidden; }
  .dhs-shift-meter i { position: absolute; inset: 0 auto 0 0; width: calc(var(--v, 0) * 100%); border-radius: 3px; background: var(--dhs-shift-starter); transition: width 420ms var(--dhs-shift-ease), background-color 300ms; }
  .dhs-shift-meters li[data-over] .dhs-shift-meter i { background: var(--dhs-shift-hot); }
  .dhs-shift-meter s { position: absolute; top: -1px; bottom: -1px; left: 50%; width: 2px; background: var(--dhs-shift-ink); opacity: 0.7; }
  .dhs-shift-meters li[data-prime] { padding-top: 8px; border-top: 1px dashed var(--dhs-shift-line2); font-weight: 650; }

  .dhs-shift-floor { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 5px; }
  .dhs-shift-tbl { position: relative; display: grid; place-items: center; height: 38px; border-radius: 8px; font: 650 10.5px var(--dhs-shift-mono); color: var(--dhs-shift-muted); background: var(--dhs-shift-sunk); box-shadow: inset 0 0 0 1px var(--dhs-shift-line); transition: background-color 260ms, color 260ms, box-shadow 200ms, scale 260ms var(--dhs-shift-spring); }
  .dhs-shift-tbl[data-w="2"] { grid-column: span 2; }
  .dhs-shift-tbl::after { content: attr(data-cov); position: absolute; right: 4px; bottom: 2px; font-size: 9px; opacity: 0.8; }
  .dhs-shift-tbl:hover { box-shadow: inset 0 0 0 1px var(--dhs-shift-line2); }
  .dhs-shift-tbl[data-st] { color: var(--dhs-shift-bg); }
  .dhs-shift-tbl[data-st="seated"] { background: color-mix(in oklch, var(--dhs-shift-ink) 55%, var(--dhs-shift-bg)); }
  .dhs-shift-tbl[data-st="starter"] { background: var(--dhs-shift-starter); }
  .dhs-shift-tbl[data-st="main"] { background: var(--dhs-shift-main); }
  .dhs-shift-tbl[data-st="dessert"] { background: var(--dhs-shift-dessert); }
  .dhs-shift-tbl[data-st="bill"] { background: color-mix(in oklch, var(--dhs-shift-hot) 70%, var(--dhs-shift-bg)); }
  .dhs-shift-tbl[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--dhs-shift-bg), 0 0 0 3.5px var(--dhs-shift-ink); scale: 1.04; z-index: 1; }
  .dhs-shift-flegend { display: flex; flex-wrap: wrap; gap: 2px 10px; margin-top: 8px; font-size: 10.5px; color: var(--dhs-shift-faint); }
  .dhs-shift-flegend li { display: flex; align-items: center; gap: 4px; }
  .dhs-shift-flegend li::before { content: ""; width: 7px; height: 7px; border-radius: 2px; background: var(--sw); }
  .dhs-shift-flegend [data-st="seated"] { --sw: color-mix(in oklch, var(--dhs-shift-ink) 55%, var(--dhs-shift-bg)); }
  .dhs-shift-flegend [data-st="starter"] { --sw: var(--dhs-shift-starter); }
  .dhs-shift-flegend [data-st="main"] { --sw: var(--dhs-shift-main); }
  .dhs-shift-flegend [data-st="dessert"] { --sw: var(--dhs-shift-dessert); }
  .dhs-shift-flegend [data-st="bill"] { --sw: color-mix(in oklch, var(--dhs-shift-hot) 70%, var(--dhs-shift-bg)); }
  .dhs-shift-floorinfo { margin-top: 9px; min-height: 34px; font-size: 11.5px; color: var(--dhs-shift-muted); }
  .dhs-shift-floorinfo b { color: var(--dhs-shift-ink); font-weight: 650; }

  /* ---------- tickets ---------- */
  .dhs-shift-tickets, .dhs-shift-labour { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 10px; }
  .dhs-shift-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; }
  .dhs-shift-toolbar .dhs-shift-note { margin-left: auto; }
  .dhs-shift-chips { display: flex; flex-wrap: wrap; gap: 5px; }
  .dhs-shift-chips button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--dhs-shift-muted); box-shadow: inset 0 0 0 1px var(--dhs-shift-line2); transition: background-color 160ms, color 160ms; }
  .dhs-shift-chips button::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: currentColor; opacity: 0.5; transition: scale 260ms var(--dhs-shift-spring), opacity 160ms; }
  .dhs-shift-chips [aria-pressed="true"] { color: var(--dhs-shift-ink); background: var(--dhs-shift-raise); }
  .dhs-shift-chips [aria-pressed="true"]::before { opacity: 1; background: var(--dhs-shift-accent); scale: 1.2; }
  .dhs-shift-chips em { font: 500 10.5px var(--dhs-shift-mono); font-style: normal; color: var(--dhs-shift-faint); }
  .dhs-shift-check { display: inline-flex; align-items: center; gap: 7px; font-size: 12px; color: var(--dhs-shift-muted); cursor: pointer; }
  .dhs-shift-check input { width: 15px; height: 15px; margin: 0; }
  .dhs-shift-tbody { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; }
  .dhs-shift-tbody:has(.dhs-shift-detail:not([hidden])) { grid-template-columns: minmax(0, 1fr) clamp(220px, 28cqi, 280px); }
  .dhs-shift-scroll { min-height: 0; overflow: auto; border-radius: 12px; background: var(--dhs-shift-card); box-shadow: inset 0 0 0 1px var(--dhs-shift-line); scrollbar-width: thin; scrollbar-color: var(--dhs-shift-line2) transparent; }
  .dhs-shift-table { width: 100%; border-collapse: collapse; font-size: 12.5px; font-variant-numeric: tabular-nums; }
  .dhs-shift-table th { position: sticky; top: 0; z-index: 1; background: var(--dhs-shift-card); text-align: left; padding: 0; border-bottom: 1px solid var(--dhs-shift-line2); }
  .dhs-shift-table th button { width: 100%; display: flex; align-items: center; gap: 4px; padding: 9px 12px; font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dhs-shift-muted); }
  .dhs-shift-table th button:hover { color: var(--dhs-shift-ink); }
  .dhs-shift-table th button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; opacity: 0; transition: opacity 160ms, rotate 220ms var(--dhs-shift-ease); }
  .dhs-shift-table th[aria-sort="ascending"] button::after { opacity: 1; border-bottom-color: var(--dhs-shift-accent); translate: 0 -2px; }
