  ['Rafael Duarte', 'Kitchen porter', 'boh', 13.8, '17:00', '23:30', 0],
  ['Sam Whitlock', 'Kitchen porter', 'boh', 13.8, '18:00', '23:30', 2],
  ['Priya Raman', 'General manager', 'foh', 25.2, '15:00', '23:30', 0],
  ['Ollie Brandt', 'Supervisor', 'foh', 18, '16:30', '23:30', 0],
  ['Hana Sato', 'Server', 'foh', 14.4, '17:00', '23:00', 0],
  ['Luca Ferri', 'Server', 'foh', 14.4, '17:00', '23:00', 0],
  ['Ama Boateng', 'Server', 'foh', 14.4, '18:00', '23:30', 1],
