      if (r() < want) {
        const size = tb.cap === 2 ? (r() < 0.12 ? 1 : 2) : Math.max(2, tb.cap - (r() < 0.4 ? 1 : 0) - (r() < 0.15 ? 1 : 0));
        let dur = Math.round(58 + size * 8 + (r() - 0.5) * 26);
        if (t + dur > T1 - 30) dur = T1 - 30 - t;
        if (dur < 55) break;
        const sales = size * Math.round(d.spend * (0.8 + r() * 0.42));
        const food = Math.round(sales * (0.7 + r() * 0.08)), bev = sales - food;
        const s = { table: tb.id, size, seat: t, close: t + dur, sales, food, bev,
