        if (st) addTicket(s, 'starter', t + 8 + Math.floor(r() * 6), Math.max(1, size - (r() < 0.3 ? 1 : 0)));
        const mainAt = t + (st ? 30 + Math.floor(r() * 10) : 13 + Math.floor(r() * 6));
        addTicket(s, 'main', mainAt, size);
        if (r() < 0.6 && t + dur - 24 > mainAt + 28) addTicket(s, 'dessert', t + dur - 22 - Math.floor(r() * 5), Math.max(1, size - (r() < 0.45 ? 1 : 0)));
        t += dur + 6 + Math.floor(r() * 16);
