  tix.sort((a, b) => a.fire - b.fire);
  tix.forEach((k, i) => {
    let load = 0;
    for (let j = i - 1; j >= 0 && tix[j].fire > k.fire - 15; j--) load += tix[j].items.length;
    const base = { starter: 6.5, main: 10.5, dessert: 5 }[k.course];
    k.min = Math.round((base + load * 0.17 + k.items.length * 0.3 + r() * 3.4 - 1) * 10) / 10;
    k.pass = k.fire + k.min;
    k.no = 'K' + (201 + i);
    k.late = k.min > TARGET[k.course];
  });
