}

/* ------------------------------------------------------------------ state */
let D = null, T = 20 * 60 + 10, view = 'service', pickTable = null, pickTicket = null, pickStaff = null, team = 'all';
const stations = { Cold: true, 'Sauté': true, Grill: true, Pastry: true };
