  const t = $('.dhs-shift-toast');
  t.textContent = msg;
  t.removeAttribute('data-show'); void t.offsetWidth; t.setAttribute('data-show', '');
}
function setText(k, v) { const n = $('[data-k="' + k + '"]'); if (n && n.textContent !== v) n.textContent = v; }
const tip = $('.dhs-shift-tip');
function showTip(html, x, y) {
  tip.innerHTML = html; tip.hidden = false;
  const R = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let lx = x - R.left + 14, ly = y - R.top - h - 10;
  if (lx + w > R.width - 8) lx = x - R.left - w - 14;
  if (ly < 8) ly = y - R.top + 16;
  tip.style.translate = Math.max(8, lx) + 'px ' + Math.min(R.height - h - 8, ly) + 'px';
}
function hideTip() { tip.hidden = true; }
const row = (a, b) => '<div><span>' + a + '</span><span>' + b + '</span></div>';

/* ------------------------------------------------------------------ chart */
const chart = $('.dhs-shift-chart'), svg = $('.dhs-shift-svg'), pill = $('.dhs-shift-pill');
let G = null;   /* geometry of the last render */

function drawChart() {
  const W = chart.clientWidth, H = chart.clientHeight;
  if (W < 40 || H < 40) return;
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  svg.textContent = '';
  const ml = 34, mr = 10, mt = 22, mb = 20, gap = 16;
  const ph = H - mt - mb - gap, h1 = Math.round(ph * 0.56), h2 = ph - h1;
  const y1b = mt + h1, y2t = y1b + gap, y2b = y2t + h2;
  const x = (t) => ml + ((t - T0) / (T1 - T0)) * (W - ml - mr);
  const cmax = Math.ceil(SEATS / 10) * 10 + 10;
  const y1 = (v) => y1b - (v / cmax) * h1;
  const tmax = 30, y2 = (v) => y2b - (Math.min(v, tmax) / tmax) * h2;
  G = { W, H, ml, mr, mt, y1b, y2t, y2b, x, y1, y2, inv: (px) => T0 + ((px - ml) / (W - ml - mr)) * (T1 - T0) };

  const defs = el('defs', {}, svg);
  const pat = el('pattern', { id: UID + '-hatch', width: 6, height: 6, patternUnits: 'userSpaceOnUse', patternTransform: 'rotate(45)' }, defs);
  el('line', { x1: 0, y1: 0, x2: 0, y2: 6, class: 'dhs-shift-futurehatch' }, pat);

  const grid = el('g', { class: 'dhs-shift-grid' }, svg);
  for (let v = 0; v <= cmax; v += 20) {
    el('line', { x1: ml, x2: W - mr, y1: y1(v), y2: y1(v) }, grid);
    el('text', { x: ml - 6, y: y1(v) + 3, 'text-anchor': 'end' }, grid).textContent = v;
  }
  for (let v = 0; v <= tmax; v += 10) {
    el('line', { x1: ml, x2: W - mr, y1: y2(v), y2: y2(v) }, grid);
    el('text', { x: ml - 6, y: y2(v) + 3, 'text-anchor': 'end' }, grid).textContent = v;
  }
  const ax = el('g', { class: 'dhs-shift-ax' }, svg);
  const step = W < 520 ? 120 : 60;
  for (let t = T0; t <= T1; t += 30) {
    if ((t - T0) % step) continue;
    el('text', { x: x(t), y: H - 4, 'text-anchor': 'middle' }, ax).textContent = clock(t);
  }
  el('text', { x: ml, y: mt - 9, class: 'dhs-shift-axlabel' }, ax).textContent = 'Covers';
  el('text', { x: ml, y: y2t + 1, class: 'dhs-shift-axlabel' }, ax).textContent = 'Ticket, min';

  el('line', { x1: ml, x2: W - mr, y1: y1(SEATS), y2: y1(SEATS), class: 'dhs-shift-cap' }, svg);
  el('text', { x: W - mr, y: y1(SEATS) - 4, 'text-anchor': 'end', class: 'dhs-shift-captext' }, svg).textContent = SEATS + ' seats';

  /* seated per 15 minutes */
  const cols = el('g', {}, svg), bw = Math.max(2, (x(T0 + 15) - x(T0)) * 0.62);
  for (let b = 0, t = T0; t < T1; t += 15, b++) {
    let n = 0;
    for (const s of D.seats) if (s.seat >= t && s.seat < t + 15) n += s.size;
    if (!n) continue;
    const r = el('rect', { x: x(t + 7.5) - bw / 2, y: y1(n), width: bw, height: y1b - y1(n), rx: 1.5, class: 'dhs-shift-col' }, cols);
    r.style.setProperty('--i', b);
  }
  /* covers in house, sampled every 5 minutes */
  let pts = [];
  for (let t = T0; t <= T1; t += 5) {
    let n = 0;
    for (const s of D.seats) if (s.seat <= t && t < s.close) n += s.size;
    pts.push([x(t), y1(n)]);
  }
  const line = 'M' + pts.map((p) => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join('L');
  const hg = el('g', { class: 'dhs-shift-houseg' }, svg);
  el('path', { d: line + 'L' + x(T1) + ',' + y1b + 'L' + x(T0) + ',' + y1b + 'Z', class: 'dhs-shift-area' }, hg);
  el('path', { d: line, class: 'dhs-shift-areaLine' }, hg);

  el('line', { x1: ml, x2: W - mr, y1: y2(TARGET.main), y2: y2(TARGET.main), class: 'dhs-shift-target' }, svg);
  el('text', { x: W - mr, y: y2(TARGET.main) - 4, 'text-anchor': 'end', class: 'dhs-shift-targettext' }, svg).textContent = 'Mains target ' + TARGET.main + ' min';

  const dots = el('g', { class: 'dhs-shift-dots' }, svg);
  D.tix.forEach((k) => {
    const c = el('circle', { cx: x(k.fire).toFixed(1), cy: y2(k.min).toFixed(1), r: 3.4, class: 'dhs-shift-dot', 'data-c': k.course }, dots);
    if (k.late) c.setAttribute('data-late', '');
    c.style.setProperty('--i', Math.round((k.fire - T0) / 15));
    k.node = c;
  });

  G.future = el('rect', { y: mt - 6, height: y2b - mt + 6, class: 'dhs-shift-future' }, svg);
  G.hatch = el('rect', { y: mt - 6, height: y2b - mt + 6, fill: 'url(#' + UID + '-hatch)' }, svg);
  G.scrub = el('line', { y1: mt - 6, y2: y2b, class: 'dhs-shift-scrub' }, svg);
  G.hover = el('line', { y1: mt - 6, y2: y2b, class: 'dhs-shift-hover', visibility: 'hidden' }, svg);
  markTable();
  placeScrub();
}

function placeScrub() {
  if (!G) return;
  const px = G.x(T), w = Math.max(0, G.W - G.mr - px);
  G.future.setAttribute('x', px); G.future.setAttribute('width', w);
  G.hatch.setAttribute('x', px); G.hatch.setAttribute('width', w);
  G.scrub.setAttribute('x1', px); G.scrub.setAttribute('x2', px);
  pill.textContent = clock(T);
  pill.style.left = Math.min(G.W - 24, Math.max(24, px)) + 'px';
}

function markTable() {
  if (!G) return;
  if (pickTable) svg.setAttribute('data-pick', ''); else svg.removeAttribute('data-pick');
  D.tix.forEach((k) => { if (!k.node) return; if (pickTable && k.table === pickTable) k.node.setAttribute('data-mine', ''); else k.node.removeAttribute('data-mine'); });
}

function setT(t, from) {
  t = Math.max(T0, Math.min(T1, Math.round(t)));
  if (t === T && from !== 'force') return;
  T = t;
  chart.setAttribute('aria-valuenow', T);
  chart.setAttribute('aria-valuetext', clock(T));
  const endBtn = $('[data-act="end"]');
  endBtn.disabled = T >= T1;
  endBtn.title = T >= T1 ? 'Already showing the full service' : 'Jump to the end of service';
  placeScrub();
  update();
}

chart.addEventListener('pointerdown', (e) => {
  if (!G || e.button !== 0) return;
  stop();
  chart.setPointerCapture(e.pointerId);
  const R = chart.getBoundingClientRect();
  setT(G.inv(e.clientX - R.left));
});
chart.addEventListener('pointermove', (e) => {
  if (!G) return;
  const R = chart.getBoundingClientRect(), px = e.clientX - R.left, py = e.clientY - R.top;
  if (chart.hasPointerCapture && chart.hasPointerCapture(e.pointerId)) { setT(G.inv(px)); hideTip(); return; }
  const t = Math.max(T0, Math.min(T1, G.inv(px)));
  G.hover.setAttribute('visibility', 'visible');
  G.hover.setAttribute('x1', G.x(t)); G.hover.setAttribute('x2', G.x(t));
  if (py > G.y2t - 4) {
    let best = null, bd = 100;
    for (const k of D.tix) {
      const dx = G.x(k.fire) - px, dy = G.y2(k.min) - py, dd = dx * dx + dy * dy;
      if (dd < bd) { bd = dd; best = k; }
    }
    if (best) {
      showTip('<b>' + best.no + ' · ' + best.table + ' · ' + COURSE[best.course] + '</b>' +
        row('Station', best.station) + row('Fired', clock(best.fire)) + row('Ticket', best.min.toFixed(1) + ' min') +
        row('Target', TARGET[best.course] + ' min') + row('Items', best.items.length), e.clientX, e.clientY);
      return;
    }
  }
  const b0 = T0 + Math.floor((t - T0) / 15) * 15;
  let seated = 0, house = 0, fired = 0;
  for (const s of D.seats) { if (s.seat >= b0 && s.seat < b0 + 15) seated += s.size; if (s.seat <= t && t < s.close) house += s.size; }
  const mins = [];
  for (const k of D.tix) if (k.fire >= b0 && k.fire < b0 + 15) { fired++; mins.push(k.min); }
  mins.sort((a, b) => a - b);
  showTip('<b>' + clock(t) + (t > T ? ' · not yet happened' : '') + '</b>' + row('In house', house + ' covers') +
    row('Seated ' + clock(b0) + '–' + clock(b0 + 15), seated) + row('Tickets fired', fired) +
    row('Median ticket', mins.length ? quant(mins, 0.5).toFixed(1) + ' min' : '—'), e.clientX, e.clientY);
});
chart.addEventListener('pointerleave', () => { if (G) G.hover.setAttribute('visibility', 'hidden'); hideTip(); });
chart.addEventListener('keydown', (e) => {
  const k = e.key, big = e.shiftKey ? 15 : 5;
  let t = null;
  if (k === 'ArrowLeft' || k === 'ArrowDown') t = T - big;
  else if (k === 'ArrowRight' || k === 'ArrowUp') t = T + big;
  else if (k === 'PageDown') t = T - 30;
  else if (k === 'PageUp') t = T + 30;
  else if (k === 'Home') t = T0;
  else if (k === 'End') t = T1;
  if (t === null) return;
  e.preventDefault(); stop(); setT(t);
});

/* ------------------------------------------------------------------ replay */
const playBtn = $('[data-act="play"]');
let playT = T;
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!playing) return;
  if (!visible || document.hidden) { last = 0; return; }
  const dt = last ? Math.min(64, now - last) : 16;
  last = now;
  if (RM.matches) {
    /* calm version: whole quarter-hours, no sweeping */
    if (now - (frame.step || 0) > 650) { frame.step = now; playT = Math.floor(playT / 15) * 15 + 15; setT(playT); }
  } else {
    playT += dt * 0.03;          /* 30 service minutes per second */
    setT(playT);
  }
  if (T >= T1) { stop(); toast('Replay finished · ' + DAYS[D.di].short + ' ' + DAYS[D.di].date); return; }
  raf = requestAnimationFrame(frame);
}
function start() {
  if (T >= T1) setT(T0, 'force');
  playT = T; playing = true; last = 0;
  playBtn.setAttribute('aria-pressed', 'true'); playBtn.querySelector('span').textContent = 'Pause';
  if (!raf) raf = requestAnimationFrame(frame);
}
function stop() {
  playing = false;
  playBtn.setAttribute('aria-pressed', 'false'); playBtn.querySelector('span').textContent = 'Replay';
  if (raf) { cancelAnimationFrame(raf); raf = 0; }
}
playBtn.addEventListener('click', () => (playing ? stop() : start()));
$('[data-act="end"]').addEventListener('click', () => { stop(); setT(T1); });
const io = new IntersectionObserver((es) => {
  visible = es[es.length - 1].isIntersecting;
  if (visible && playing && !raf) raf = requestAnimationFrame(frame);
});
io.observe(root);
function onVis() {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden && playing && !raf) { last = 0; raf = requestAnimationFrame(frame); }
}
document.addEventListener('visibilitychange', onVis);

/* ------------------------------------------------------------------ update */
function update() {
  const s = stats(T);
  setText('time', clock(T));
  setText('covers', String(s.covers));
  setText('covers-s', s.house + ' in house now');
  setText('sales', gbp(s.sales));
  setText('sales-s', 'closed checks · ' + Math.round(s.food / Math.max(1, s.sales) * 100) + '% food');
  setText('spend', s.closed ? gbp(s.sales / s.closed, 2) : '—');
  setText('turns', (s.seatings / TABLES.length).toFixed(2));
  setText('turns-s', s.seatings + ' seatings');
  setText('ticket', isFinite(s.p50) ? s.p50.toFixed(1) + ' min' : '—');
  setText('ticket-s', isFinite(s.p90) ? 'median · p90 ' + s.p90.toFixed(1) : 'none passed yet');
  setText('food', pct(s.foodPct));
  setText('food-s', gbp(s.fc) + ' at cost');
  setText('labour', pct(s.labPct));
  setText('labour-s', gbp(s.labour) + ' so far');
  const tone = (n, v, tg) => { const d = $('[data-k="' + n + '"]'); if (!isFinite(v)) d.removeAttribute('data-tone'); else d.dataset.tone = v > tg ? 'hot' : 'ok'; };
  setText('primek', pct(s.prime));
  tone('food', s.foodPct, TARGET.food); tone('labour', s.labPct, TARGET.labour); tone('primek', s.prime, TARGET.prime);
  tone('ticket', s.p50, TARGET.main);
  setText('navtix', String(D.tix.filter((k) => k.fire <= T).length));
  /* prime cost meters: the target sits at the middle of each track */
  const M = [['Food cost', s.foodPct, TARGET.food], ['Drinks cost', s.bevPct, TARGET.bev], ['Labour', s.labPct, TARGET.labour], ['Prime cost', s.prime, TARGET.prime]];
  $$('.dhs-shift-meters li').forEach((li, i) => {
    const [, v, tg] = M[i];
    li.querySelector('b').textContent = pct(v);
    li.querySelector('i').style.setProperty('--v', isFinite(v) ? Math.min(1, v / (tg * 2)).toFixed(3) : 0);
    li.toggleAttribute('data-over', isFinite(v) && v > tg);
  });
  setText('prime', isFinite(s.prime) ? gbp(s.fc + s.bc + s.labour) + ' of ' + gbp(s.sales) : 'no closed checks yet');
  paintFloor();
  if (view === 'tickets') renderTickets();
  if (view === 'labour') paintLabour();
}

/* ------------------------------------------------------------------ floor */
const floor = $('.dhs-shift-floor');
function seatingAt(id, t) { return D.seats.find((s) => s.table === id && s.seat <= t && t < s.close); }
function stageOf(s, t) {
  if (t >= s.close - 10) return 'bill';
  let st = 'seated';
  for (const k of s.tix) if (k.fire <= t) st = k.course;
  return st;
}
function buildFloor() {
  floor.textContent = '';
  TABLES.forEach((tb) => {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'dhs-shift-tbl'; b.dataset.id = tb.id; b.dataset.w = tb.w;
    b.setAttribute('aria-pressed', String(pickTable === tb.id));
    b.textContent = tb.id;
    b.addEventListener('click', () => { pickTable = pickTable === tb.id ? null : tb.id; paintFloor(); markTable(); });
    b.addEventListener('pointerenter', (e) => {
      const s = seatingAt(tb.id, T);
      showTip('<b>' + tb.id + ' · ' + tb.cap + ' seats</b>' + (s ? row('Covers', s.size) + row('Seated', clock(s.seat)) +
        row('Stage', { seated: 'Ordering', starter: 'Starters', main: 'Mains', dessert: 'Dessert', bill: 'Bill' }[stageOf(s, T)]) +
        row('Check', gbp(s.sales, 2)) : row('Status', 'Free at ' + clock(T))), e.clientX, e.clientY);
    });
    b.addEventListener('pointerleave', hideTip);
    floor.appendChild(b);
  });
}
function paintFloor() {
  let occ = 0, cov = 0;
  $$('.dhs-shift-tbl', floor).forEach((b) => {
    const s = seatingAt(b.dataset.id, T);
    if (s) { occ++; cov += s.size; b.dataset.st = stageOf(s, T); b.dataset.cov = s.size; }
    else { b.removeAttribute('data-st'); b.dataset.cov = ''; }
    b.setAttribute('aria-pressed', String(pickTable === b.dataset.id));
    b.setAttribute('aria-label', b.dataset.id + (s ? ', ' + s.size + ' covers, ' + b.dataset.st : ', free'));
  });
  setText('floor-n', occ + ' of ' + TABLES.length + ' tables · ' + cov + ' covers');
  const info = $('[data-k="floor-info"]');
  if (!pickTable) { info.textContent = 'Pick a table to trace its tickets on the chart.'; return; }
  const all = D.seats.filter((s) => s.table === pickTable), now = seatingAt(pickTable, T);
  const done = all.filter((s) => s.seat <= T);
  const next = all.find((s) => s.seat > T);
  info.innerHTML = '<b>' + pickTable + '</b> · ' + done.length + ' of ' + all.length + ' seatings so far, ' +
    gbp(done.filter((s) => s.close <= T).reduce((a, s) => a + s.sales, 0)) + ' closed. ' +
    (now ? 'Now: ' + now.size + ' covers since ' + clock(now.seat) + '.' : next ? 'Next seated ' + clock(next.seat) + '.' : 'No more seatings.');
}

/* ------------------------------------------------------------------ tickets */
const tbody = $('.dhs-shift-table tbody'), detail = $('.dhs-shift-detail');
const chips = $('.dhs-shift-chips');
Object.keys(stations).forEach((st) => {
  const b = document.createElement('button');
  b.type = 'button'; b.dataset.st = st; b.setAttribute('aria-pressed', 'true');
  b.innerHTML = st + ' <em></em>';
  b.addEventListener('click', () => { stations[st] = !stations[st]; b.setAttribute('aria-pressed', String(stations[st])); renderTickets(); });
  chips.appendChild(b);
});
$('[data-k="late"]').addEventListener('change', (e) => { lateOnly = e.target.checked; renderTickets(); });
$$('.dhs-shift-table th button').forEach((b) => b.addEventListener('click', () => {
  const k = b.dataset.sort;
  sort = { k, dir: sort.k === k ? -sort.dir : (k === 'min' || k === 'items' ? -1 : 1) };
  $$('.dhs-shift-table th').forEach((th) => th.setAttribute('aria-sort', th.contains(b) ? (sort.dir > 0 ? 'ascending' : 'descending') : 'none'));
  renderTickets();
}));
/* a ticket as the pass saw it at time T: still open tickets count their elapsed minutes */
const tnow = (k) => { const passed = k.pass <= T, v = passed ? k.min : Math.round((T - k.fire) * 10) / 10; return { passed, v, late: v > TARGET[k.course] }; };
function ticketList() {
  const order = { starter: 0, main: 1, dessert: 2 };
  const val = (k) => sort.k === 'table' ? +k.table.slice(1) : sort.k === 'course' ? order[k.course] : sort.k === 'items' ? k.items.length : sort.k === 'min' ? tnow(k).v : k[sort.k];
  return D.tix.filter((k) => k.fire <= T && stations[k.station] && (!lateOnly || tnow(k).late))
    .sort((a, b) => { const va = val(a), vb = val(b); return (va > vb ? 1 : va < vb ? -1 : a.fire - b.fire) * sort.dir; });
}
function renderTickets() {
  const list = ticketList();
  $$('button', chips).forEach((b) => { b.querySelector('em').textContent = D.tix.filter((k) => k.fire <= T && k.station === b.dataset.st).length; });
  setText('tcount', list.length + ' tickets · ' + list.filter((k) => tnow(k).late).length + ' over target · ' + list.filter((k) => !tnow(k).passed).length + ' open');
  $('.dhs-shift-empty').hidden = list.length > 0;
  const frag = document.createDocumentFragment();
  list.forEach((k, i) => {
    const tr = document.createElement('tr');
    tr.tabIndex = pickTicket === k ? 0 : (pickTicket || i ? -1 : 0);
    tr.setAttribute('aria-selected', String(pickTicket === k));
    tr._k = k;
    const st = tnow(k), passed = st.passed;
    if (st.late) tr.dataset.late = '';
    if (k.flag) tr.dataset.flag = '';
    tr.innerHTML = '<td>' + clock(k.fire) + ' <small style="color:var(--dhs-shift-faint)">' + k.no + '</small></td><td>' + k.table + '</td><td data-c="' + k.course + '">' + COURSE[k.course] +
      '</td><td>' + k.station + '</td><td class="dhs-shift-num">' + k.items.length + '</td><td class="dhs-shift-num"><span class="dhs-shift-bar"><i style="--v:' +
      Math.min(1, st.v / 30).toFixed(3) + '"></i><b>' + (passed ? st.v.toFixed(1) : 'open ' + Math.round(st.v) + 'm') + '</b></span></td>';
    frag.appendChild(tr);
  });
  tbody.textContent = '';
  tbody.appendChild(frag);
  if (pickTicket && !list.includes(pickTicket)) closeDetail();
}
function openDetail(k) {
  pickTicket = k;
  $$('tr', tbody).forEach((tr) => { tr.setAttribute('aria-selected', String(tr._k === k)); tr.tabIndex = tr._k === k ? 0 : -1; });
  detail.hidden = false;
  $('[data-d="sub"]', detail).textContent = k.table + ' · ' + k.station;
  $('[data-d="title"]', detail).textContent = k.no + ' · ' + COURSE[k.course];
  const st = tnow(k), passed = st.passed;
  $('[data-d="facts"]', detail).innerHTML = '<dt>Fired</dt><dd>' + clock(k.fire) + '</dd><dt>Passed</dt><dd>' + (passed ? clock(k.pass) : 'still open at ' + clock(T)) +
    '</dd><dt>' + (passed ? 'Ticket time' : 'Open for') + '</dt><dd' + (st.late ? ' data-tone="hot"' : '') + '>' + st.v.toFixed(1) + ' min</dd><dt>Target</dt><dd>' + TARGET[k.course] +
    ' min</dd><dt>Party</dt><dd>' + k.seat.size + ' covers, seated ' + clock(k.seat.seat) + '</dd>';
  const counts = {};
  k.items.forEach((n) => { counts[n] = (counts[n] || 0) + 1; });
  $('[data-d="items"]', detail).innerHTML = Object.keys(counts).map((n) => '<li><b>' + counts[n] + '×</b>' + n + '</li>').join('');
  const fb = $('[data-act="flag"]', detail);
  fb.setAttribute('aria-pressed', String(k.flag));
  fb.querySelector('span').textContent = k.flag ? 'Flagged for the debrief' : 'Flag for the debrief';
}
function closeDetail() {
  detail.hidden = true; pickTicket = null;
  $$('tr', tbody).forEach((tr, i) => { tr.setAttribute('aria-selected', 'false'); tr.tabIndex = i ? -1 : 0; });
}
tbody.addEventListener('click', (e) => { const tr = e.target.closest('tr'); if (tr && tr._k) { openDetail(tr._k); tr.focus({ preventScroll: true }); } });
tbody.addEventListener('keydown', (e) => {
  const tr = e.target.closest('tr'); if (!tr) return;
  const rows = $$('tr', tbody), i = rows.indexOf(tr);
  let n = null;
  if (e.key === 'ArrowDown') n = rows[i + 1];
  else if (e.key === 'ArrowUp') n = rows[i - 1];
  else if (e.key === 'Home') n = rows[0];
  else if (e.key === 'End') n = rows[rows.length - 1];
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openDetail(tr._k); return; }
  else if (e.key === 'Escape') { closeDetail(); return; }
  if (n) { e.preventDefault(); rows.forEach((r) => (r.tabIndex = -1)); n.tabIndex = 0; n.focus(); if (!detail.hidden) openDetail(n._k); }
});
$('[data-act="close"]').addEventListener('click', () => { const k = pickTicket; closeDetail(); const tr = $$('tr', tbody).find((r) => r._k === k); if (tr) tr.focus(); });
detail.addEventListener('keydown', (e) => { if (e.key === 'Escape') { e.preventDefault(); closeDetail(); } });
$('[data-act="flag"]').addEventListener('click', () => {
  if (!pickTicket) return;
  pickTicket.flag = !pickTicket.flag;
  const k = pickTicket;
  renderTickets(); openDetail(k);
  toast(k.flag ? k.no + ' flagged for the debrief' : k.no + ' flag removed');
});

/* ------------------------------------------------------------------ labour */
const grows = $('.dhs-shift-grows'), gaxis = $('.dhs-shift-gaxis');
const LX = (t) => (t - L0) / (T1 - L0);
function buildLabour() {
  gaxis.innerHTML = '';
  for (let t = L0; t <= T1; t += 60) gaxis.insertAdjacentHTML('beforeend', '<i style="left:' + (LX(t) * 100).toFixed(2) + '%"></i><span style="left:' + (LX(t) * 100).toFixed(2) + '%">' + clock(t).slice(0, 2) + '</span>');
  grows.textContent = '';
  const list = D.staff.filter((p) => team === 'all' || p.team === team);
  list.forEach((p, i) => {
    const li = document.createElement('li');
    li.className = 'dhs-shift-grow'; li.setAttribute('role', 'option'); li.dataset.team = p.team; li._p = p;
    li.setAttribute('aria-selected', String(pickStaff === p)); li.tabIndex = (pickStaff ? pickStaff === p : i === 0) ? 0 : -1;
    li.style.setProperty('--i', i);
    li.innerHTML = '<span class="dhs-shift-gname"><b>' + p.n + '</b><small>' + p.role + ' · £' + p.rate.toFixed(2) + '/h loaded</small></span>' +
      '<span class="dhs-shift-gtrack"><span class="dhs-shift-gbar" style="--a:' + LX(p.s).toFixed(4) + ';--b:' + LX(p.e).toFixed(4) + '"><i></i></span></span><span class="dhs-shift-gcost"></span>';
    grows.appendChild(li);
  });
  paintLabour();
}
function paintLabour() {
  grows.style.setProperty('--tx', LX(T).toFixed(4));
  let tot = 0, sch = 0, on = 0;
  $$('.dhs-shift-grow', grows).forEach((li) => {
    const p = li._p, worked = Math.max(0, Math.min(T, p.e) - p.s), cost = Math.round(p.rate * 100 * worked / 60);
    tot += cost; sch += Math.round(p.rate * 100 * (p.e - p.s) / 60);
    if (T >= p.s && T < p.e) on++;
    li.querySelector('.dhs-shift-gbar i').style.setProperty('--w', (worked / (p.e - p.s)).toFixed(4));
    li.querySelector('.dhs-shift-gcost').textContent = gbp(cost, 2);
  });
  const s = stats(T);
  const hrs = D.staff.filter((p) => team === 'all' || p.team === team).reduce((a, p) => a + Math.max(0, Math.min(T, p.e) - p.s) / 60, 0);
  setText('lsum', on + ' on the clock · ' + gbp(tot) + ' of ' + gbp(sch) + ' · ' + (hrs ? gbp(s.sales / hrs) : '£0') + ' sales per labour hour');
  pickLine();
}
function pickLine() {
  const n = $('[data-k="lpick"]');
  if (!pickStaff) { n.textContent = 'Select a row to see that shift against the clock.'; return; }
  const p = pickStaff, worked = Math.max(0, Math.min(T, p.e) - p.s);
  n.innerHTML = '<b>' + p.n + '</b> · ' + p.role + ' · ' + clock(p.s) + '–' + clock(p.e) + ' · ' + (worked / 60).toFixed(2) + ' of ' +
    ((p.e - p.s) / 60).toFixed(2) + ' h worked · ' + gbp(Math.round(p.rate * 100 * worked / 60), 2) + ' so far';
}
function selectStaff(li) {
  pickStaff = li._p;
  $$('.dhs-shift-grow', grows).forEach((r) => { r.setAttribute('aria-selected', String(r === li)); r.tabIndex = r === li ? 0 : -1; });
