}
grows.addEventListener('click', (e) => { const li = e.target.closest('.dhs-shift-grow'); if (li) selectStaff(li); });
grows.addEventListener('keydown', (e) => {
  const li = e.target.closest('.dhs-shift-grow'); if (!li) return;
  const rows = $$('.dhs-shift-grow', grows), i = rows.indexOf(li);
  const n = e.key === 'ArrowDown' ? rows[i + 1] : e.key === 'ArrowUp' ? rows[i - 1] : e.key === 'Home' ? rows[0] : e.key === 'End' ? rows[rows.length - 1] : null;
  if (n) { e.preventDefault(); selectStaff(n); n.focus(); }
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectStaff(li); }
});
const seg = $('.dhs-shift-seg');
seg.addEventListener('click', (e) => {
  const b = e.target.closest('button'); if (!b) return;
  team = b.dataset.team;
  $$('button', seg).forEach((x) => { x.setAttribute('aria-checked', String(x === b)); x.tabIndex = x === b ? 0 : -1; });
  if (pickStaff && team !== 'all' && pickStaff.team !== team) pickStaff = null;
  buildLabour();
});
seg.addEventListener('keydown', (e) => {
  if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
  const bs = $$('button', seg), i = bs.findIndex((b) => b.getAttribute('aria-checked') === 'true');
  const n = bs[(i + (e.key === 'ArrowRight' ? 1 : bs.length - 1)) % bs.length];
  e.preventDefault(); n.focus(); n.click();
});

/* ------------------------------------------------------------------ nav + days */
const nav = $('.dhs-shift-nav');
function go(v) {
  view = v;
  $$('button', nav).forEach((b) => { const on = b.dataset.view === v; b.setAttribute('aria-selected', String(on)); b.tabIndex = on ? 0 : -1; });
  $$('.dhs-shift-pane').forEach((p) => { p.hidden = p.dataset.pane !== v; });
