  if (v === 'tickets') renderTickets();
  if (v === 'labour') buildLabour();
}
nav.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) go(b.dataset.view); });
nav.addEventListener('keydown', (e) => {
  const keys = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 };
  if (!(e.key in keys)) return;
  const bs = $$('button', nav), i = bs.indexOf(document.activeElement);
  const n = bs[(i + keys[e.key] + bs.length) % bs.length];
  e.preventDefault(); n.focus(); go(n.dataset.view);
});

const days = $('.dhs-shift-days');
const DATA = DAYS.map((_, i) => build(i));
DAYS.forEach((d, i) => {
  const b = document.createElement('button');
  b.type = 'button'; b.setAttribute('role', 'radio'); b.dataset.day = i;
  const cov = DATA[i].seats.reduce((a, s) => a + s.size, 0);
  b.innerHTML = '<b>' + d.short + '</b><small>' + d.date + '</small><em>' + cov + ' cov</em>';
