});
days.addEventListener('keydown', (e) => {
  if (!/^Arrow/.test(e.key)) return;
  const bs = $$('button', days), i = bs.findIndex((b) => b.getAttribute('aria-checked') === 'true');
  const n = bs[(i + (e.key === 'ArrowDown' || e.key === 'ArrowRight' ? 1 : bs.length - 1)) % bs.length];
  e.preventDefault(); n.focus(); n.click();
});

function loadDay(i, animate) {
  stop();
  D = DATA[i];
  pickTable = null; pickTicket = null; pickStaff = null;
  detail.hidden = true;
  $$('button', days).forEach((b) => { const on = +b.dataset.day === i; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; });
  setText('date', DAYS[i].short + ' ' + DAYS[i].date + ' · Dinner 17:00–23:30');
  $('.dhs-shift-meters').innerHTML = ['Food cost', 'Drinks cost', 'Labour', 'Prime cost'].map((n, j) =>
    '<li' + (j === 3 ? ' data-prime' : '') + '><span>' + n + ' <small style="color:var(--dhs-shift-faint)">/ ' + [TARGET.food, TARGET.bev, TARGET.labour, TARGET.prime][j] + '%</small></span><b></b><span class="dhs-shift-meter"><i></i><s></s></span></li>').join('');
  buildFloor();
  if (view === 'service') drawChart();
  if (view === 'labour') buildLabour();
  setT(T, 'force');
  if (animate && !RM.matches && view === 'service') svg.animate([{ opacity: 0.25, filter: 'blur(2px)' }, { opacity: 1, filter: 'blur(0)' }], { duration: 380, easing: 'cubic-bezier(0.22, 0.9, 0.24, 1)' });
}

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (view === 'service') { drawChart(); }
});
ro.observe(chart);

root.setAttribute('data-enter', '');
loadDay(2, false);
setTimeout(() => root.removeAttribute('data-enter'), 1900);

