@keyframes dhs-revpar-grow { from { scale: 1 0; } }
@keyframes dhs-revpar-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dhs-revpar-pop { from { opacity: 0; scale: 0.3; } }
@keyframes dhs-revpar-fade { from { opacity: 0; translate: 0 6px; } }

@property --dhs-revpar-sweep { syntax: "<angle>"; inherits: false; initial-value: 0deg; }

.dhs-revpar {
  /* re-theme with these four */
  --dhs-revpar-bg: oklch(0.982 0.004 230);
  --dhs-revpar-ink: oklch(0.25 0.028 245);
  --dhs-revpar-accent: oklch(0.52 0.095 195);
  --dhs-revpar-warm: oklch(0.74 0.13 75);
  /* segment palette */
  --dhs-revpar-s1: var(--dhs-revpar-accent);
  --dhs-revpar-s2: oklch(0.42 0.07 258);
  --dhs-revpar-s3: oklch(0.74 0.09 165);
  --dhs-revpar-s4: var(--dhs-revpar-warm);
  --dhs-revpar-s5: oklch(0.65 0.13 38);
  --dhs-revpar-up: oklch(0.54 0.13 155);
  --dhs-revpar-down: oklch(0.57 0.18 28);
  /* derived */
  --dhs-revpar-card: color-mix(in oklch, var(--dhs-revpar-bg), white 70%);
  --dhs-revpar-side: color-mix(in oklch, var(--dhs-revpar-bg), var(--dhs-revpar-accent) 5%);
  --dhs-revpar-line: color-mix(in oklch, var(--dhs-revpar-ink) 10%, transparent);
  --dhs-revpar-line2: color-mix(in oklch, var(--dhs-revpar-ink) 18%, transparent);
  --dhs-revpar-muted: color-mix(in oklch, var(--dhs-revpar-ink) 64%, var(--dhs-revpar-bg));
  --dhs-revpar-faint: color-mix(in oklch, var(--dhs-revpar-ink) 44%, var(--dhs-revpar-bg));
  --dhs-revpar-hover: color-mix(in oklch, var(--dhs-revpar-accent) 7%, transparent);
  --dhs-revpar-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dhs-revpar-spring: linear(0, 0.03, 0.12 5%, 0.53 13%, 0.9 20%, 1.06 27%, 1.08 32%, 1.04 40%, 0.99 52%, 1);
  --dhs-revpar-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dhs-revpar-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhs-revpar-bg);
  color: var(--dhs-revpar-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dhs-revpar-accent);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dhs-revpar-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dhs-revpar-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  [data-seg="tra"] { --sc: var(--dhs-revpar-s1); }
  [data-seg="cor"] { --sc: var(--dhs-revpar-s2); }
  [data-seg="grp"] { --sc: var(--dhs-revpar-s3); }
  [data-seg="ota"] { --sc: var(--dhs-revpar-s4); }
  [data-seg="whl"] { --sc: var(--dhs-revpar-s5); }

  .dhs-revpar-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dhs-revpar-muted); }
  .dhs-revpar-note { font-size: 11.5px; color: var(--dhs-revpar-muted); font-variant-numeric: tabular-nums; }
  .dhs-revpar-app { display: grid; height: 100%; grid-template-columns: 206px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dhs-revpar-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px 14px; background: var(--dhs-revpar-side); border-right: 1px solid var(--dhs-revpar-line); scrollbar-width: thin; scrollbar-color: var(--dhs-revpar-line2) transparent; }
  .dhs-revpar-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
