  .dhs-revpar-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dhs-revpar-brand b { font-size: 14px; font-weight: 720; letter-spacing: -0.015em; }
  .dhs-revpar-brand small { font-size: 11px; color: var(--dhs-revpar-muted); }
  .dhs-revpar-nav { display: grid; gap: 2px; }
  .dhs-revpar-nav button { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--dhs-revpar-muted); font-weight: 580; transition: background-color 160ms, color 160ms; }
  .dhs-revpar-nav button:hover { color: var(--dhs-revpar-ink); background: var(--dhs-revpar-hover); }
  .dhs-revpar-nav [aria-selected="true"] { color: var(--dhs-revpar-ink); background: var(--dhs-revpar-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--dhs-revpar-ink) 12%, transparent), inset 0 0 0 1px var(--dhs-revpar-line); }
  .dhs-revpar-nav svg { flex: none; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-revpar-nav [aria-selected="true"] svg { stroke: var(--dhs-revpar-accent); }
  .dhs-revpar-segs { display: grid; gap: 2px; }
  .dhs-revpar-segs legend { padding: 0 6px 6px; }
  .dhs-revpar-segs label { display: grid; grid-template-columns: 14px 1fr auto; align-items: center; gap: 9px; padding: 6px 8px; border-radius: 8px; cursor: pointer; font-size: 12.5px; transition: background-color 150ms, opacity 200ms; }
  .dhs-revpar-segs label:hover { background: var(--dhs-revpar-hover); }
  .dhs-revpar-segs input { position: absolute; opacity: 0; pointer-events: none; }
  .dhs-revpar-segs label:has(:focus-visible) { outline: 2px solid var(--dhs-revpar-accent); outline-offset: 1px; }
  .dhs-revpar-segs i { width: 14px; height: 14px; border-radius: 4px; background: var(--sc); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--sc), black 15%); transition: scale 260ms var(--dhs-revpar-spring), background-color 200ms; }
  .dhs-revpar-segs label:has(input:not(:checked)) { opacity: 0.5; }
  .dhs-revpar-segs label:has(input:not(:checked)) i { background: transparent; scale: 0.75; }
  .dhs-revpar-segs em { font: 500 11px var(--dhs-revpar-mono); font-style: normal; color: var(--dhs-revpar-faint); font-variant-numeric: tabular-nums; }
  .dhs-revpar-foot { margin-top: auto; padding: 0 6px; font-size: 11px; color: var(--dhs-revpar-faint); }

  /* ---------- main ---------- */
  .dhs-revpar-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dhs-revpar-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 20px; padding: 16px 18px 12px; }
  .dhs-revpar-title { display: grid; gap: 3px; }
  .dhs-revpar-title h2 { font-size: clamp(19px, 0.75rem + 1.25cqi, 26px); font-weight: 730; letter-spacing: -0.03em; line-height: 1.05; }
  .dhs-revpar-range { display: inline-flex; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--dhs-revpar-ink) 5%, transparent); }
  .dhs-revpar-range button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dhs-revpar-muted); transition: color 160ms, background-color 160ms, box-shadow 160ms; }
  .dhs-revpar-range button:hover { color: var(--dhs-revpar-ink); }
  .dhs-revpar-range [aria-checked="true"] { color: var(--dhs-revpar-ink); background: var(--dhs-revpar-card); box-shadow: 0 1px 3px color-mix(in oklch, var(--dhs-revpar-ink) 16%, transparent); }

  .dhs-revpar-view { min-height: 0; overflow: auto; padding: 0 18px 16px; scrollbar-width: thin; scrollbar-color: var(--dhs-revpar-line2) transparent; }
  .dhs-revpar-card { min-width: 0; border-radius: 13px; background: var(--dhs-revpar-card); box-shadow: 0 0 0 1px var(--dhs-revpar-line), 0 1px 2px color-mix(in oklch, var(--dhs-revpar-ink) 6%, transparent); padding: 12px 14px; }
  .dhs-revpar-cardhead { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 12px; margin-bottom: 6px; }
  .dhs-revpar-cardhead h3 { font-size: 12.5px; font-weight: 690; }
  .dhs-revpar-swline { display: inline-block; width: 14px; height: 2px; margin-right: 6px; vertical-align: middle; background: var(--dhs-revpar-ink); border-radius: 1px; }

  .dhs-revpar-perf { display: grid; gap: 12px; grid-template-columns: minmax(0, 1.65fr) minmax(0, 1fr); grid-template-rows: auto minmax(220px, 1fr) auto; grid-template-areas: "kpi kpi" "daily iso" "seg day"; }
  .dhs-revpar-kpis { grid-area: kpi; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
  .dhs-revpar-kpi { position: relative; display: grid; grid-template-columns: 1fr auto; grid-template-rows: auto auto 26px; gap: 0 8px; padding: 11px 14px 8px; border-radius: 13px; background: var(--dhs-revpar-card); box-shadow: 0 0 0 1px var(--dhs-revpar-line), 0 1px 2px color-mix(in oklch, var(--dhs-revpar-ink) 6%, transparent); overflow: hidden; animation: dhs-revpar-fade 520ms var(--dhs-revpar-ease) both; animation-delay: calc(var(--i) * 60ms); }
  .dhs-revpar-kpi dt { font-size: 11.5px; font-weight: 600; color: var(--dhs-revpar-muted); }
  .dhs-revpar-kpi dd { grid-row: 2; font-size: clamp(18px, 0.6rem + 1.3cqi, 25px); font-weight: 730; letter-spacing: -0.03em; line-height: 1.15; font-variant-numeric: tabular-nums; }
  .dhs-revpar-kpi dd small { font-size: 0.55em; font-weight: 600; color: var(--dhs-revpar-faint); margin-left: 2px; letter-spacing: 0; }
