  .dhs-revpar-spark path + path { fill: color-mix(in oklch, var(--dhs-revpar-accent) 10%, transparent); stroke: none; }

  .dhs-revpar-daily { grid-area: daily; display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; }
  .dhs-revpar-iso { grid-area: iso; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; }
  .dhs-revpar-isonote { margin-top: 4px; font-size: 11px; color: var(--dhs-revpar-faint); }
  .dhs-revpar-plot { position: relative; min-height: 150px; cursor: crosshair; border-radius: 6px; }
  .dhs-revpar-plot > svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dhs-revpar-plot svg {
    .dhs-revpar-gl { stroke: var(--dhs-revpar-line); shape-rendering: crispEdges; }
    .dhs-revpar-gt { fill: var(--dhs-revpar-faint); font: 500 10px var(--dhs-revpar-mono); font-variant-numeric: tabular-nums; }
    .dhs-revpar-wk { fill: color-mix(in oklch, var(--dhs-revpar-ink) 3.5%, transparent); }
    .dhs-revpar-bar { fill: var(--sc); transform-box: fill-box; transform-origin: 50% 100%; transition: y 460ms var(--dhs-revpar-ease), height 460ms var(--dhs-revpar-ease), opacity 200ms; }
