  --dhs-rooms-a1: oklch(0.56 0.14 330);
  --dhs-rooms-a2: oklch(0.6 0.1 200);
  --dhs-rooms-a3: oklch(0.7 0.13 95);
  --dhs-rooms-a4: oklch(0.6 0.11 165);
  /* surfaces */
