  --dhs-rooms-stone: color-mix(in oklch, var(--dhs-rooms-bg), var(--dhs-rooms-ink) 9%);
  --dhs-rooms-stone2: color-mix(in oklch, var(--dhs-rooms-bg), var(--dhs-rooms-ink) 16%);
  --dhs-rooms-glass: color-mix(in oklch, var(--dhs-rooms-ink) 62%, oklch(0.5 0.04 240));
  --dhs-rooms-line: color-mix(in oklch, var(--dhs-rooms-ink) 10%, transparent);
  --dhs-rooms-line2: color-mix(in oklch, var(--dhs-rooms-ink) 19%, transparent);
  --dhs-rooms-muted: color-mix(in oklch, var(--dhs-rooms-ink) 64%, var(--dhs-rooms-bg));
  --dhs-rooms-faint: color-mix(in oklch, var(--dhs-rooms-ink) 44%, var(--dhs-rooms-bg));
  --dhs-rooms-ease: cubic-bezier(0.22, 0.85, 0.25, 1);
  --dhs-rooms-spring: linear(0, 0.03, 0.12 5%, 0.53 13%, 0.9 20%, 1.06 27%, 1.08 32%, 1.04 40%, 0.99 52%, 1);
  --dhs-rooms-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dhs-rooms-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhs-rooms-bg);
  color: var(--dhs-rooms-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dhs-rooms-accent);
