  [data-s="clean"] { --sc: var(--dhs-rooms-clean); }
  [data-s="insp"] { --sc: var(--dhs-rooms-insp); }
  [data-s="ooo"] { --sc: var(--dhs-rooms-ooo); }
  [data-a="0"] { --ac: var(--dhs-rooms-a0); }
  [data-a="1"] { --ac: var(--dhs-rooms-a1); }
  [data-a="2"] { --ac: var(--dhs-rooms-a2); }
  [data-a="3"] { --ac: var(--dhs-rooms-a3); }
  [data-a="4"] { --ac: var(--dhs-rooms-a4); }

  .dhs-rooms-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .dhs-rooms-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dhs-rooms-muted); }
  .dhs-rooms-note { font-size: 11.5px; color: var(--dhs-rooms-muted); font-variant-numeric: tabular-nums; }
  .dhs-rooms-app { display: grid; height: 100%; grid-template-columns: 68px minmax(0, 1fr); grid-template-areas: "rail main"; }

  /* ---------- rail ---------- */
  .dhs-rooms-rail { grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 18px; padding: 16px 8px; background: var(--dhs-rooms-ink); color: var(--dhs-rooms-bg); }
  .dhs-rooms-mark svg { width: 34px; height: 34px; padding: 6px; border-radius: 10px; background: color-mix(in oklch, var(--dhs-rooms-bg) 14%, transparent); fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-rooms-tabs { display: grid; gap: 6px; }
  .dhs-rooms-tabs button { display: grid; justify-items: center; gap: 3px; width: 54px; padding: 8px 2px 6px; border-radius: 10px; color: color-mix(in oklch, var(--dhs-rooms-bg) 62%, var(--dhs-rooms-ink)); font-size: 10px; font-weight: 620; letter-spacing: 0.02em; transition: background-color 160ms, color 160ms; }
  .dhs-rooms-tabs button:hover { color: var(--dhs-rooms-bg); background: color-mix(in oklch, var(--dhs-rooms-bg) 8%, transparent); }
  .dhs-rooms-tabs [aria-selected="true"] { color: var(--dhs-rooms-ink); background: var(--dhs-rooms-bg); }
  .dhs-rooms-tabs svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-rooms-rail :focus-visible { outline-color: var(--dhs-rooms-bg); }

  /* ---------- main ---------- */
  .dhs-rooms-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dhs-rooms-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 24px; padding: 16px 18px 12px; }
  .dhs-rooms-title { display: grid; gap: 3px; }
  .dhs-rooms-title h2 { font-size: clamp(20px, 0.8rem + 1.3cqi, 27px); font-weight: 760; letter-spacing: -0.035em; line-height: 1.05; }
  .dhs-rooms-kpis { display: flex; flex-wrap: wrap; gap: 6px 22px; }
  .dhs-rooms-kpis div { display: grid; gap: 1px; }
  .dhs-rooms-kpis dt { font-size: 11px; color: var(--dhs-rooms-muted); white-space: nowrap; }
  .dhs-rooms-kpis dd { font-size: 19px; font-weight: 730; letter-spacing: -0.02em; line-height: 1.15; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dhs-rooms-kpis dd small { margin-left: 2px; font-size: 12px; font-weight: 550; color: var(--dhs-rooms-faint); }
  .dhs-rooms-kpis dd[data-tone="hot"] { color: var(--dhs-rooms-hot); }
  .dhs-rooms-pane { min-height: 0; padding: 0 18px 16px; }

  /* ---------- board ---------- */
  .dhs-rooms-board { display: grid; grid-template-columns: minmax(0, 1fr) clamp(250px, 29cqi, 320px); gap: 14px; }
  .dhs-rooms-facadecard { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 10px; }
  .dhs-rooms-legend { display: flex; flex-wrap: wrap; gap: 5px; }
  .dhs-rooms-legend label { display: inline-flex; align-items: center; gap: 5px; height: 25px; padding: 0 9px 0 7px; border-radius: 99px; font-size: 11.5px; font-weight: 600; cursor: pointer; background: var(--dhs-rooms-card); box-shadow: inset 0 0 0 1px var(--dhs-rooms-line2); transition: opacity 160ms, background-color 160ms; }
  .dhs-rooms-legend label:hover { background: color-mix(in oklch, var(--dhs-rooms-card), var(--dhs-rooms-ink) 5%); }
  .dhs-rooms-legend input { position: absolute; opacity: 0; pointer-events: none; }
  .dhs-rooms-legend label:has(:focus-visible) { outline: 2px solid var(--dhs-rooms-ink); outline-offset: 1px; }
  .dhs-rooms-legend i { width: 11px; height: 11px; border-radius: 3px; background: var(--sc); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dhs-rooms-ink) 18%, transparent); transition: scale 240ms var(--dhs-rooms-spring); }
  .dhs-rooms-legend [data-s="prog"] i { background: repeating-linear-gradient(-45deg, var(--dhs-rooms-dirty) 0 3px, color-mix(in oklch, var(--dhs-rooms-dirty) 40%, var(--dhs-rooms-bg)) 3px 6px); }
  .dhs-rooms-legend [data-s="ooo"] i { background: repeating-linear-gradient(45deg, var(--dhs-rooms-ooo) 0 2px, var(--dhs-rooms-card) 2px 4px); }
  .dhs-rooms-legend em { font: 500 10.5px var(--dhs-rooms-mono); font-style: normal; color: var(--dhs-rooms-faint); }
  .dhs-rooms-legend label:has(input:not(:checked)) { opacity: 0.45; }
  .dhs-rooms-legend label:has(input:not(:checked)) i { scale: 0.55; }
  /* the legend filters the facade with :has() alone */
  &:has(.dhs-rooms-legend input[value="occ"]:not(:checked)) .dhs-rooms-win[data-s="occ"],
  &:has(.dhs-rooms-legend input[value="due"]:not(:checked)) .dhs-rooms-win[data-s="due"],
  &:has(.dhs-rooms-legend input[value="dirty"]:not(:checked)) .dhs-rooms-win[data-s="dirty"],
  &:has(.dhs-rooms-legend input[value="prog"]:not(:checked)) .dhs-rooms-win[data-s="prog"],
  &:has(.dhs-rooms-legend input[value="clean"]:not(:checked)) .dhs-rooms-win[data-s="clean"],
  &:has(.dhs-rooms-legend input[value="insp"]:not(:checked)) .dhs-rooms-win[data-s="insp"],
  &:has(.dhs-rooms-legend input[value="ooo"]:not(:checked)) .dhs-rooms-win[data-s="ooo"] { opacity: 0.14; filter: grayscale(1); }

  .dhs-rooms-scroll { min-height: 0; overflow: auto; border-radius: 14px; background: linear-gradient(180deg in oklch, color-mix(in oklch, oklch(0.9 0.04 230), var(--dhs-rooms-bg) 45%), var(--dhs-rooms-bg) 70%); box-shadow: inset 0 0 0 1px var(--dhs-rooms-line); scrollbar-width: thin; scrollbar-color: var(--dhs-rooms-line2) transparent; }
  .dhs-rooms-facade {
    --g: 5px;
    position: relative; width: min(100%, 640px); margin: 16px auto 0; padding: 0 16px; display: grid; row-gap: 7px; column-gap: var(--g);
    grid-template-columns: 22px repeat(3, minmax(0, 1fr)) 3px repeat(3, minmax(0, 1fr)) 3px repeat(3, minmax(0, 1fr)) 3px repeat(3, minmax(0, 1fr)) 22px;
    background: linear-gradient(90deg, transparent 0 16px, var(--dhs-rooms-stone) 16px calc(100% - 16px), transparent 0);
  }
  .dhs-rooms-cornice { grid-column: 1 / -1; position: relative; display: grid; place-items: center; height: 34px; margin: 0 -16px; border-radius: 6px 6px 2px 2px; background: var(--dhs-rooms-stone2); box-shadow: 0 3px 0 color-mix(in oklch, var(--dhs-rooms-ink) 10%, transparent); font-size: 10.5px; font-weight: 750; letter-spacing: 0.42em; text-transform: uppercase; color: color-mix(in oklch, var(--dhs-rooms-ink) 72%, var(--dhs-rooms-bg)); padding-left: 0.42em; }
  .dhs-rooms-floor { grid-column: 1; align-self: center; text-align: center; font: 650 10.5px var(--dhs-rooms-mono); color: var(--dhs-rooms-faint); }
  .dhs-rooms-pil { align-self: stretch; background: var(--dhs-rooms-stone2); border-radius: 1px; }
  .dhs-rooms-win {
    position: relative; display: grid; place-items: end start; aspect-ratio: 1 / 1.04; min-height: 26px; padding: 2px 3px; border-radius: 4px 4px 2px 2px;
    background: var(--sc, var(--dhs-rooms-glass)); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--dhs-rooms-ink) 22%, transparent), 0 2px 0 var(--dhs-rooms-stone2);
    font: 650 9.5px/1 var(--dhs-rooms-mono); color: color-mix(in oklch, var(--dhs-rooms-ink) 80%, transparent); font-variant-numeric: tabular-nums;
    transition: opacity 220ms, filter 220ms, scale 260ms var(--dhs-rooms-spring), background-color 300ms, box-shadow 200ms;
    animation: dhs-rooms-lit 520ms var(--dhs-rooms-ease) both; animation-delay: calc(var(--i) * 9ms);
  }
  .dhs-rooms-win::before { content: ""; position: absolute; left: 50%; top: 3px; bottom: 5px; width: 1.5px; margin-left: -0.75px; background: color-mix(in oklch, var(--dhs-rooms-ink) 16%, transparent); }
  .dhs-rooms-win::after { content: ""; position: absolute; left: 2px; right: 2px; bottom: 2px; height: 3px; border-radius: 2px; background: var(--ac, transparent); opacity: 0.95; }
  .dhs-rooms-win[data-suite] { aspect-ratio: auto; }
  .dhs-rooms-win[data-s="insp"], .dhs-rooms-win[data-s="dirty"], .dhs-rooms-win[data-s="prog"] { color: var(--dhs-rooms-card); }
  .dhs-rooms-win[data-s="occ"] { background: radial-gradient(120% 90% at 50% 15%, color-mix(in oklch, var(--dhs-rooms-occ), white 45%), var(--dhs-rooms-occ)); }
  .dhs-rooms-win[data-s="prog"] { background: repeating-linear-gradient(-45deg, var(--dhs-rooms-dirty) 0 4px, color-mix(in oklch, var(--dhs-rooms-dirty) 55%, var(--dhs-rooms-bg)) 4px 8px); background-size: 16px 100%; animation: dhs-rooms-lit 520ms var(--dhs-rooms-ease) both, dhs-rooms-mop 900ms linear infinite; }
  .dhs-rooms-win[data-s="ooo"] { background: repeating-linear-gradient(45deg, var(--dhs-rooms-ooo) 0 2px, var(--dhs-rooms-stone) 2px 5px); }
  .dhs-rooms-win:hover { scale: 1.1; z-index: 2; box-shadow: inset 0 0 0 1.5px var(--dhs-rooms-ink), 0 6px 14px color-mix(in oklch, var(--dhs-rooms-ink) 25%, transparent); }
  .dhs-rooms-win[aria-pressed="true"] { z-index: 3; box-shadow: inset 0 0 0 2px var(--dhs-rooms-ink), 0 0 0 2.5px var(--dhs-rooms-card), 0 0 0 4px var(--dhs-rooms-ink); animation: dhs-rooms-ping 1.4s var(--dhs-rooms-ease) infinite; }
  .dhs-rooms-win b { position: absolute; top: 2px; right: 2px; display: flex; gap: 1px; }
  .dhs-rooms-win b svg { width: 10px; height: 10px; padding: 1px; border-radius: 3px; background: var(--dhs-rooms-card); fill: none; stroke: var(--dhs-rooms-ink); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-rooms-win b svg[data-g="prio"] { background: var(--dhs-rooms-ink); stroke: var(--dhs-rooms-card); }
  .dhs-rooms-board[data-focus] .dhs-rooms-win:not([data-match]) { opacity: 0.22; filter: saturate(0.3); }
  .dhs-rooms-ground { grid-column: 2 / -2; display: grid; grid-template-columns: 1fr 1.4fr 1fr; align-items: end; gap: 10px; height: 52px; padding: 8px 6px 0; }
  .dhs-rooms-ground i { height: 100%; border-radius: 3px 3px 0 0; background: linear-gradient(var(--dhs-rooms-glass), color-mix(in oklch, var(--dhs-rooms-glass) 70%, var(--dhs-rooms-bg))); opacity: 0.55; }
  .dhs-rooms-ground i:nth-child(2) { border-radius: 40px 40px 0 0; opacity: 0.75; }
  .dhs-rooms-street { grid-column: 1 / -1; height: 8px; margin: 0 -16px; background: var(--dhs-rooms-stone2); border-radius: 2px; }

  /* ---------- lanes ---------- */
  .dhs-rooms-lanescol { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 10px; }
  .dhs-rooms-lanehead { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
  .dhs-rooms-lanehead h3 { font-size: 13px; font-weight: 700; }
  .dhs-rooms-lanehead div { display: grid; }
  .dhs-rooms-btn { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px 0 10px; border-radius: 9px; font-size: 12.5px; font-weight: 650; background: var(--dhs-rooms-card); box-shadow: inset 0 0 0 1px var(--dhs-rooms-line2); transition: background-color 150ms, scale 220ms var(--dhs-rooms-spring), opacity 150ms; }
  .dhs-rooms-btn:hover { background: color-mix(in oklch, var(--dhs-rooms-card), var(--dhs-rooms-ink) 6%); }
  .dhs-rooms-btn:active { scale: 0.96; }
  .dhs-rooms-btn:disabled { opacity: 0.4; cursor: not-allowed; }
  .dhs-rooms-btn svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-rooms-primary { background: var(--dhs-rooms-ink); color: var(--dhs-rooms-bg); box-shadow: none; }
  .dhs-rooms-primary:hover { background: color-mix(in oklch, var(--dhs-rooms-ink), var(--dhs-rooms-bg) 16%); }
  .dhs-rooms-lanes { min-height: 0; overflow: auto; display: grid; align-content: start; gap: 8px; padding: 2px; scrollbar-width: thin; scrollbar-color: var(--dhs-rooms-line2) transparent; }
  .dhs-rooms-lane { display: grid; gap: 7px; padding: 10px 11px; border-radius: 12px; background: var(--dhs-rooms-card); box-shadow: inset 0 0 0 1px var(--dhs-rooms-line); transition: box-shadow 160ms, background-color 160ms; animation: dhs-rooms-rise 460ms var(--dhs-rooms-ease) both; animation-delay: calc(140ms + var(--i) * 60ms); }
  .dhs-rooms-lane:has(.dhs-rooms-who-btn[aria-pressed="true"]) { box-shadow: inset 0 0 0 1.5px var(--ac), 0 4px 14px color-mix(in oklch, var(--ac) 18%, transparent); }
  .dhs-rooms-who-btn { display: grid; grid-template-columns: 26px 1fr auto; align-items: center; gap: 9px; width: 100%; text-align: left; border-radius: 8px; }
  .dhs-rooms-av { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; background: var(--ac); color: var(--dhs-rooms-card); font-size: 10.5px; font-weight: 750; }
  .dhs-rooms-who-btn b { display: block; font-size: 12.5px; font-weight: 650; line-height: 1.2; }
  .dhs-rooms-who-btn small { font-size: 10.5px; color: var(--dhs-rooms-muted); font-variant-numeric: tabular-nums; }
  .dhs-rooms-who-btn em { font: 650 11px var(--dhs-rooms-mono); font-style: normal; font-variant-numeric: tabular-nums; }
  .dhs-rooms-who-btn em[data-over] { color: var(--dhs-rooms-hot); }
  .dhs-rooms-load { position: relative; height: 6px; border-radius: 3px; background: var(--dhs-rooms-line); }
  .dhs-rooms-load i { position: absolute; inset: 0 auto 0 0; width: calc(min(var(--v), 1) * 100%); border-radius: 3px; background: var(--ac); transition: width 520ms var(--dhs-rooms-spring); }
  .dhs-rooms-load s { position: absolute; top: -2px; bottom: -2px; left: calc(var(--cap) * 100%); width: 2px; border-radius: 1px; background: var(--dhs-rooms-ink); opacity: 0.6; }
  .dhs-rooms-load[data-over] i { background: linear-gradient(90deg, var(--ac) calc(var(--cap) / min(var(--v), 1) * 100%), var(--dhs-rooms-hot) 0); }
  .dhs-rooms-chips { display: flex; flex-wrap: wrap; gap: 3px; }
  .dhs-rooms-chip { position: relative; display: grid; place-items: center; min-width: 32px; height: 20px; padding: 0 4px; border-radius: 5px; font: 650 10px var(--dhs-rooms-mono); font-variant-numeric: tabular-nums; background: var(--sc); color: var(--dhs-rooms-ink); transition: scale 200ms var(--dhs-rooms-spring); }
  .dhs-rooms-chip[data-s="insp"], .dhs-rooms-chip[data-s="dirty"], .dhs-rooms-chip[data-s="prog"] { color: var(--dhs-rooms-card); }
  .dhs-rooms-chip[data-s="prog"] { background: repeating-linear-gradient(-45deg, var(--dhs-rooms-dirty) 0 3px, color-mix(in oklch, var(--dhs-rooms-dirty) 55%, var(--dhs-rooms-bg)) 3px 6px); }
  .dhs-rooms-chip[data-done] { opacity: 0.5; }
  .dhs-rooms-chip[data-prio]::after { content: ""; position: absolute; top: -3px; right: -3px; width: 7px; height: 7px; border-radius: 50%; background: var(--dhs-rooms-ink); box-shadow: 0 0 0 1.5px var(--dhs-rooms-card); }
  .dhs-rooms-chip:hover { scale: 1.12; }

  /* ---------- drawer ---------- */
  .dhs-rooms-drawer {
    position: absolute; z-index: 9; top: 10px; right: 10px; bottom: 10px; width: min(320px, calc(100% - 20px)); overflow: auto;
    display: grid; align-content: start; gap: 14px; padding: 16px; border-radius: 16px; background: var(--dhs-rooms-card);
    box-shadow: 0 0 0 1px var(--dhs-rooms-line2), 0 24px 60px color-mix(in oklch, var(--dhs-rooms-ink) 26%, transparent);
    transition: translate 440ms var(--dhs-rooms-spring), opacity 240ms;
    scrollbar-width: thin;
  }
  @starting-style { .dhs-rooms-drawer { translate: 40px 0; opacity: 0; } }
  .dhs-rooms-drawer header { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
  .dhs-rooms-drawer h3 { font-size: 22px; font-weight: 760; letter-spacing: -0.03em; outline: none; }
  .dhs-rooms-x { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; color: var(--dhs-rooms-muted); }
  .dhs-rooms-x:hover { background: var(--dhs-rooms-line); color: var(--dhs-rooms-ink); }
  .dhs-rooms-x svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  .dhs-rooms-dstate { display: flex; align-items: center; gap: 9px; padding: 9px 11px; border-radius: 10px; background: color-mix(in oklch, var(--sc) 26%, var(--dhs-rooms-card)); font-weight: 650; }
  .dhs-rooms-dstate::before { content: ""; width: 12px; height: 12px; border-radius: 3px; background: var(--sc); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dhs-rooms-ink) 20%, transparent); }
  .dhs-rooms-dstate small { margin-left: auto; font: 500 11px var(--dhs-rooms-mono); color: var(--dhs-rooms-muted); }
  .dhs-rooms-dl { display: grid; grid-template-columns: auto 1fr; gap: 5px 14px; font-size: 12.5px; }
  .dhs-rooms-dl dt { color: var(--dhs-rooms-muted); }
  .dhs-rooms-dl dd { text-align: right; font-variant-numeric: tabular-nums; }
  .dhs-rooms-acts { display: grid; gap: 6px; }
  .dhs-rooms-acts .dhs-rooms-btn { justify-content: center; height: 36px; }
  .dhs-rooms-acts p { font-size: 11.5px; color: var(--dhs-rooms-faint); text-align: center; }
  .dhs-rooms-assign { display: grid; gap: 7px; padding-top: 12px; border-top: 1px solid var(--dhs-rooms-line); }
  .dhs-rooms-who { display: grid; gap: 3px; }
  .dhs-rooms-who button { display: grid; grid-template-columns: 22px 1fr auto; align-items: center; gap: 8px; padding: 5px 8px; border-radius: 8px; text-align: left; font-size: 12.5px; transition: background-color 150ms; }
  .dhs-rooms-who button:hover { background: color-mix(in oklch, var(--dhs-rooms-ink) 5%, transparent); }
  .dhs-rooms-who button[aria-checked="true"] { background: color-mix(in oklch, var(--ac) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ac) 50%, transparent); font-weight: 650; }
  .dhs-rooms-who .dhs-rooms-av { width: 22px; height: 22px; font-size: 9.5px; }
  .dhs-rooms-who em { font: 500 10.5px var(--dhs-rooms-mono); font-style: normal; color: var(--dhs-rooms-muted); }

  /* ---------- tables ---------- */
  .dhs-rooms-arr, .dhs-rooms-team { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 10px; }
  .dhs-rooms-team { grid-template-rows: minmax(0, 1fr) auto; }
  .dhs-rooms-toolbar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 14px; }
  .dhs-rooms-seg { display: inline-flex; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--dhs-rooms-ink) 6%, transparent); }
  .dhs-rooms-seg button { height: 27px; padding: 0 12px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dhs-rooms-muted); transition: background-color 150ms, color 150ms; }
  .dhs-rooms-seg button:hover { color: var(--dhs-rooms-ink); }
  .dhs-rooms-seg [aria-checked="true"] { background: var(--dhs-rooms-card); color: var(--dhs-rooms-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--dhs-rooms-ink) 16%, transparent); }
  .dhs-rooms-tablecard { min-height: 0; overflow: auto; border-radius: 13px; background: var(--dhs-rooms-card); box-shadow: inset 0 0 0 1px var(--dhs-rooms-line); scrollbar-width: thin; scrollbar-color: var(--dhs-rooms-line2) transparent; }
  .dhs-rooms-table { width: 100%; border-collapse: collapse; font-size: 12.5px; font-variant-numeric: tabular-nums; }
  .dhs-rooms-table th { position: sticky; top: 0; z-index: 1; background: var(--dhs-rooms-card); text-align: left; padding: 9px 12px; font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dhs-rooms-muted); border-bottom: 1px solid var(--dhs-rooms-line2); white-space: nowrap; }
  .dhs-rooms-table th:has(button) { padding: 0; }
  .dhs-rooms-table th button { width: 100%; display: flex; align-items: center; gap: 4px; padding: 9px 12px; font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; }
  .dhs-rooms-table th.dhs-rooms-r button { justify-content: flex-end; }
  .dhs-rooms-table th button:hover, .dhs-rooms-table th:not([aria-sort="none"]) button { color: var(--dhs-rooms-ink); }
  .dhs-rooms-table th button::after { content: ""; border: 4px solid transparent; opacity: 0; }
  .dhs-rooms-table th[aria-sort="ascending"] button::after { opacity: 1; border-bottom-color: var(--dhs-rooms-ink); translate: 0 -2px; }
  .dhs-rooms-table th[aria-sort="descending"] button::after { opacity: 1; border-top-color: var(--dhs-rooms-ink); translate: 0 2px; }
  .dhs-rooms-table td { padding: 7px 12px; border-bottom: 1px solid var(--dhs-rooms-line); white-space: nowrap; }
