const drawer = $('.dhs-rooms-drawer');
const ACT = {
  out: ['Guest checked out', (m) => { m.s = 'dirty'; }],
  start: ['Start cleaning', (m) => { m.s = 'prog'; }],
  service: ['Start service', (m) => { m.s = 'prog'; }],
  finish: ['Finish', (m) => { m.done = true; m.s = m.task === 'stay' ? 'occ' : 'clean'; m.prio = false; }],
  pass: ['Pass inspection', (m) => { m.s = 'insp'; }],
  fail: ['Fail inspection, send back', (m) => { m.s = 'dirty'; m.done = false; }],
  checkin: ['Check the guest in', (m) => { m.s = 'occ'; m.task = null; m.done = false; m.arr = null; m.prio = false; }],
  dndOn: ['Guest asked: do not disturb', (m) => { m.dnd = true; if (m.task === 'stay' && !m.done) { m.task = null; } }],
  dndOff: ['DND lifted, add a service', (m) => { m.dnd = false; m.task = 'stay'; m.done = false; m.s = 'occ'; if (m.a < 0) m.a = defaultA(m); }],
  ooo: ['Take out of order', (m) => { m.s = 'ooo'; m.task = null; m.prio = false; m.note = 'Reported 11:40 by housekeeping'; }],
  back: ['Return to service', (m) => { m.s = 'dirty'; m.task = 'dep'; m.done = false; m.note = ''; if (m.a < 0) m.a = defaultA(m); }],
  rush: ['Rush for the arrival', (m) => { m.prio = !m.prio; }],
};
const defaultA = (m) => (m.f <= 2 ? 0 : m.f === 3 ? 1 : m.f === 4 ? 2 : m.f === 5 ? 3 : 4);
function actionsFor(m) {
  const a = [];
  if (m.s === 'due') a.push('out');
  if (m.s === 'dirty') a.push('start');
  if (m.s === 'prog') a.push('finish');
  if (m.s === 'clean') a.push('pass', 'fail');
  if (m.s === 'insp' && m.arr) a.push('checkin');
  if (m.s === 'occ' && m.task === 'stay' && !m.done) a.push('service');
  if (m.s === 'occ' && !m.dnd && !(m.task === 'stay' && m.done)) a.push('dndOn');
  if (m.s === 'occ' && m.dnd) a.push('dndOff');
  if (m.arr && m.task && !m.done) a.push('rush');
  a.push(m.s === 'ooo' ? 'back' : 'ooo');
  return a;
}
function openRoom(no, focus) {
  if (openNo === no) { closeRoom(); return; }
  const prev = openNo; openNo = no;
  if (prev) paintRoom(ROOMS.find((x) => x.no === prev));
  renderDrawer();
  paintRoom(ROOMS.find((x) => x.no === no));
  if (focus) $('[data-d="title"]', drawer).focus({ preventScroll: true });
}
function closeRoom() {
  const no = openNo; openNo = null; drawer.hidden = true;
  if (no) { const m = ROOMS.find((x) => x.no === no); paintRoom(m); const w = win(no); if (w && w.offsetParent) w.focus({ preventScroll: true }); }
}
function renderDrawer() {
  const m = ROOMS.find((x) => x.no === openNo); if (!m) { drawer.hidden = true; return; }
  drawer.hidden = false;
  $('[data-d="sub"]', drawer).textContent = 'Floor ' + m.f + ' · ' + m.type;
  $('[data-d="title"]', drawer).textContent = 'Room ' + m.no;
  const st = $('[data-d="state"]', drawer);
  st.dataset.s = m.s;
  st.innerHTML = STATE[m.s] + (m.task === 'stay' && m.done ? ', serviced' : '') + '<small>' + (m.task ? (m.task === 'dep' ? 'departure' : 'stayover') + (m.done ? ' done' : ' · ' + left(m) + ' min left') : 'no task') + '</small>';
  $('[data-d="facts"]', drawer).innerHTML =
    (m.arr ? '<dt>Arrival</dt><dd>' + clock(m.arr) + ' · ' + m.guest + (m.vip ? ' <span class="dhs-rooms-vip">VIP</span>' : '') + '</dd>' : '<dt>Arrival</dt><dd>none today</dd>') +
    '<dt>Do not disturb</dt><dd>' + (m.dnd ? 'Yes' : 'No') + '</dd>' + (m.prio ? '<dt>Priority</dt><dd>Rushed for arrival</dd>' : '') + (m.note ? '<dt>Note</dt><dd>' + m.note + '</dd>' : '');
  $('[data-d="acts"]', drawer).innerHTML = actionsFor(m).map((k, i) => '<button type="button" class="dhs-rooms-btn' + (i === 0 && k !== 'ooo' ? ' dhs-rooms-primary' : '') + '" data-do="' + k + '"' +
    (k === 'rush' ? ' aria-pressed="' + m.prio + '"' : '') + '>' + (k === 'rush' && m.prio ? 'Rushed · undo' : ACT[k][0]) + '</button>').join('');
  const who = $('[data-d="who"]', drawer), canMove = m.task && !m.done && m.s !== 'prog';
  who.innerHTML = ATT.map((p, a) => '<button type="button" role="radio" data-a="' + a + '" aria-checked="' + (m.a === a && !!m.task) + '"' + (canMove ? '' : ' disabled title="' + (m.task ? (m.done ? 'Already done' : 'Being cleaned right now') : 'No housekeeping task on this room') + '"') +
    ' tabindex="' + (m.a === a ? 0 : -1) + '"><span class="dhs-rooms-av">' + p.i + '</span>' + p.n + '<em>' + load(a).left + 'm</em></button>').join('');
}
drawer.addEventListener('click', (e) => {
  const m = ROOMS.find((x) => x.no === openNo); if (!m) return;
  if (e.target.closest('[data-act="close"]')) { closeRoom(); return; }
  const b = e.target.closest('[data-do]');
  if (b) {
    const k = b.dataset.do;
    ACT[k][1](m);
    flipKeyed('.dhs-rooms-chip', () => renderAll());
    toast('Room ' + m.no + ' · ' + (k === 'rush' ? (m.prio ? 'rushed to the top of ' + ATT[m.a].n.split(' ')[0] + '’s list' : 'no longer rushed') : STATE[m.s].toLowerCase()));
    const nb = $('[data-do]', drawer); if (nb) nb.focus({ preventScroll: true });
    return;
  }
  const w = e.target.closest('[role="radio"]');
  if (w && !w.disabled && +w.dataset.a !== m.a) {
    const from = m.a; m.a = +w.dataset.a;
    flipKeyed('.dhs-rooms-chip', () => renderAll());
    toast('Room ' + m.no + ' moved from ' + ATT[from].n.split(' ')[0] + ' to ' + ATT[m.a].n.split(' ')[0]);
  }
});
drawer.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') { e.preventDefault(); closeRoom(); return; }
  const w = e.target.closest('[role="radio"]');
  if (w && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
    e.preventDefault();
    const bs = $$('[role="radio"]', drawer).filter((x) => !x.disabled), i = bs.indexOf(w);
    const n = bs[(i + (e.key === 'ArrowDown' ? 1 : bs.length - 1)) % bs.length]; if (n) { n.focus(); n.click(); }
  }
});

/* ------------------------------------------------------------------ arrivals */
let af = 'all';
const arrBody = $('[data-t="arr"]');
function renderArr() {
  const all = ROOMS.filter((m) => m.arr).sort((p, q) => p.arr - q.arr || p.no - q.no);
  const list = all.filter((m) => af === 'all' || (af === 'wait' && m.s !== 'insp') || (af === 'vip' && m.vip));
  arrBody.innerHTML = list.map((m, i) => {
    const ready = m.s === 'insp', late = !ready && m.arr - NOW < 120;
    return '<tr style="--i:' + i + '"><td class="dhs-rooms-eta"' + (late ? ' data-late' : '') + '>' + clock(m.arr) + '</td><td>' + m.guest + (m.vip ? '<span class="dhs-rooms-vip">VIP</span>' : '') + '</td>' +
      '<td><button type="button" class="dhs-rooms-roombtn" data-no="' + m.no + '" aria-label="Open room ' + m.no + '">' + m.no + '</button></td><td><span class="dhs-rooms-pill" data-s="' + m.s + '">' + STATE[m.s] + '</span></td>' +
      '<td>' + (m.task && m.a >= 0 ? '<span class="dhs-rooms-who-cell" data-a="' + m.a + '"><i></i>' + ATT[m.a].n + '</span>' : '—') + '</td>' +
      '<td class="dhs-rooms-r"><button type="button" class="dhs-rooms-rush" data-no="' + m.no + '" aria-pressed="' + m.prio + '"' + (m.task && !m.done ? '' : ' disabled title="' + (ready ? 'Room is ready' : 'Nothing left to rush') + '"') + '>' + (m.prio ? 'Rushed' : 'Rush') + '</button></td></tr>';
  }).join('') || '<tr><td colspan="6" style="text-align:center;padding:26px;color:var(--dhs-rooms-faint)">Every arrival in this list has an inspected room.</td></tr>';
  const waiting = all.filter((m) => m.s !== 'insp').length;
  $('[data-k="arrnote"]').textContent = all.length + ' arrivals today · ' + waiting + ' still waiting on a room · now 11:40';
}
arrBody.addEventListener('click', (e) => {
  const rb = e.target.closest('.dhs-rooms-roombtn');
  if (rb) { openRoom(+rb.dataset.no, true); return; }
  const rush = e.target.closest('.dhs-rooms-rush');
  if (rush && !rush.disabled) {
    const m = ROOMS.find((x) => x.no === +rush.dataset.no);
    m.prio = !m.prio; renderAll();
    toast('Room ' + m.no + (m.prio ? ' rushed for ' + m.guest : ' back in normal order'));
  }
});
const segArr = $('.dhs-rooms-seg');
segArr.addEventListener('click', (e) => {
  const b = e.target.closest('button'); if (!b) return;
  af = b.dataset.af;
  $$('button', segArr).forEach((x) => { x.setAttribute('aria-checked', String(x === b)); x.tabIndex = x === b ? 0 : -1; });
  renderArr();
});
segArr.addEventListener('keydown', (e) => {
  if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
  const bs = $$('button', segArr), i = bs.findIndex((b) => b.getAttribute('aria-checked') === 'true');
  const n = bs[(i + (e.key === 'ArrowRight' ? 1 : bs.length - 1)) % bs.length];
  e.preventDefault(); n.focus(); n.click();
});

/* ------------------------------------------------------------------ team */
let tsort = { k: 'left', dir: -1 };
const teamBody = $('[data-t="team"]');
function renderTeam() {
  const rows = ATT.map((p, a) => { const L = load(a); return { a, n: p.n, rooms: L.rooms, done: L.done, left: L.left, finish: NOW + L.left }; });
  rows.sort((p, q) => { const va = p[tsort.k], vb = q[tsort.k]; return (va > vb ? 1 : va < vb ? -1 : 0) * tsort.dir; });
  teamBody.innerHTML = rows.map((x, i) => '<tr style="--i:' + i + '"><td><span class="dhs-rooms-who-cell" data-a="' + x.a + '"><i></i>' + x.n + '</span></td><td class="dhs-rooms-r">' + x.rooms + '</td><td class="dhs-rooms-r">' + x.done + '</td><td class="dhs-rooms-r">' + x.left + '</td>' +
    '<td><span class="dhs-rooms-fin" data-a="' + x.a + '"' + (x.finish > SHIFT_END ? ' data-over' : '') + ' style="--v:' + (x.left / CAPMIN).toFixed(3) + '"><i></i><b>' + clock(x.finish) + '</b></span></td>' +
    '<td class="dhs-rooms-r"><button type="button" class="dhs-rooms-rush" data-show="' + x.a + '">Show on board</button></td></tr>').join('');
}
$$('.dhs-rooms-team th button').forEach((b) => b.addEventListener('click', () => {
  const k = b.dataset.sort;
  tsort = { k, dir: tsort.k === k ? -tsort.dir : k === 'n' ? 1 : -1 };
  $$('.dhs-rooms-team th[aria-sort]').forEach((th) => th.setAttribute('aria-sort', th.contains(b) ? (tsort.dir > 0 ? 'ascending' : 'descending') : 'none'));
  renderTeam();
}));
teamBody.addEventListener('click', (e) => { const b = e.target.closest('[data-show]'); if (b) { go('board'); setFocus(+b.dataset.show); } });

/* ------------------------------------------------------------------ kpis + views */
function renderKpis() {
  const dep = ROOMS.filter((m) => m.task === 'dep'), stay = ROOMS.filter((m) => m.task === 'stay'), arr = ROOMS.filter((m) => m.arr);
  const ready = ROOMS.filter((m) => m.s === 'insp').length, arrReady = arr.filter((m) => m.s === 'insp').length;
  const set = (k, html) => { const d = $('[data-k="' + k + '"]'); if (d.innerHTML !== html) d.innerHTML = html; return d; };
  set('ready', ready + '<small>rooms</small>');
  set('dep', dep.filter((m) => m.done).length + '<small>/ ' + dep.length + '</small>');
  set('stay', stay.filter((m) => m.done).length + '<small>/ ' + stay.length + ' · ' + ROOMS.filter((m) => m.dnd).length + ' DND</small>');
  const early = arr.filter((m) => m.s !== 'insp' && m.arr - NOW < 120).length;
  set('arr', arrReady + '<small>/ ' + arr.length + '</small>').dataset.tone = early ? 'hot' : '';
  set('ooo', String(ROOMS.filter((m) => m.s === 'ooo').length));
  $$('label', legend).forEach((l) => { l.querySelector('em').textContent = ROOMS.filter((m) => m.s === l.dataset.s).length; });
}
let view = 'board';
function renderAll() {
  ROOMS.forEach(paintRoom);
  renderLanes(); renderKpis();
  if (view === 'arr') renderArr();
  if (view === 'team') renderTeam();
  if (openNo) renderDrawer();
}
const tabs = $('.dhs-rooms-tabs');
function go(v) {
  view = v;
  $$('button', tabs).forEach((b) => { const me = b.dataset.view === v; b.setAttribute('aria-selected', String(me)); b.tabIndex = me ? 0 : -1; });
  $$('.dhs-rooms-pane').forEach((p) => { p.hidden = p.dataset.pane !== v; });
  hideTip();
  renderAll();
}
tabs.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) go(b.dataset.view); });
tabs.addEventListener('keydown', (e) => {
  const keys = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 };
  if (!(e.key in keys)) return;
  const bs = $$('button', tabs), i = bs.indexOf(document.activeElement);
  const n = bs[(i + keys[e.key] + bs.length) % bs.length];
  e.preventDefault(); n.focus(); go(n.dataset.view);
});

buildFacade();
renderAll();

css:
@keyframes dhs-group-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dhs-group-pop { from { opacity: 0; scale: 0.2; } }
@keyframes dhs-group-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes dhs-group-cell { from { opacity: 0; scale: 0.6; } }

.dhs-group {
  /* re-theme with these four */
  --dhs-group-bg: oklch(0.205 0.014 200);
  --dhs-group-ink: oklch(0.95 0.01 190);
  --dhs-group-accent: oklch(0.8 0.13 40);
  --dhs-group-good: oklch(0.78 0.12 160);
  --dhs-group-bad: oklch(0.7 0.16 25);
  /* nine sites, one lightness, hues walked around the wheel */
  --dhs-group-c0: oklch(0.79 0.12 30);
  --dhs-group-c1: oklch(0.82 0.13 75);
  --dhs-group-c2: oklch(0.84 0.13 110);
  --dhs-group-c3: oklch(0.79 0.12 150);
  --dhs-group-c4: oklch(0.8 0.1 190);
  --dhs-group-c5: oklch(0.76 0.1 230);
  --dhs-group-c6: oklch(0.74 0.11 270);
  --dhs-group-c7: oklch(0.76 0.12 315);
  --dhs-group-c8: oklch(0.76 0.13 355);
  /* derived */
  --dhs-group-card: color-mix(in oklch, var(--dhs-group-bg), var(--dhs-group-ink) 4.5%);
  --dhs-group-raise: color-mix(in oklch, var(--dhs-group-bg), var(--dhs-group-ink) 10%);
  --dhs-group-sunk: color-mix(in oklch, var(--dhs-group-bg), black 28%);
  --dhs-group-line: color-mix(in oklch, var(--dhs-group-ink) 9%, transparent);
  --dhs-group-line2: color-mix(in oklch, var(--dhs-group-ink) 18%, transparent);
  --dhs-group-muted: color-mix(in oklch, var(--dhs-group-ink) 62%, var(--dhs-group-bg));
  --dhs-group-faint: color-mix(in oklch, var(--dhs-group-ink) 40%, var(--dhs-group-bg));
  --dhs-group-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dhs-group-spring: linear(0, 0.03, 0.12 5%, 0.53 13%, 0.9 20%, 1.06 27%, 1.08 32%, 1.04 40%, 0.99 52%, 1);
  --dhs-group-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dhs-group-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhs-group-bg);
  color: var(--dhs-group-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dhs-group-accent);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dhs-group-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  [data-site="0"] { --sc: var(--dhs-group-c0); }
  [data-site="1"] { --sc: var(--dhs-group-c1); }
  [data-site="2"] { --sc: var(--dhs-group-c2); }
  [data-site="3"] { --sc: var(--dhs-group-c3); }
  [data-site="4"] { --sc: var(--dhs-group-c4); }
  [data-site="5"] { --sc: var(--dhs-group-c5); }
  [data-site="6"] { --sc: var(--dhs-group-c6); }
  [data-site="7"] { --sc: var(--dhs-group-c7); }
  [data-site="8"] { --sc: var(--dhs-group-c8); }

  .dhs-group-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dhs-group-muted); }
  .dhs-group-note { font-size: 11.5px; color: var(--dhs-group-muted); }
  .dhs-group-app { display: grid; height: 100%; grid-template-columns: 196px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dhs-group-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px 14px; background: var(--dhs-group-sunk); border-right: 1px solid var(--dhs-group-line); scrollbar-width: thin; scrollbar-color: var(--dhs-group-line2) transparent; }
  .dhs-group-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
  .dhs-group-brand svg { flex: none; width: 32px; height: 32px; padding: 5px; border-radius: 50%; background: color-mix(in oklch, var(--dhs-group-good) 18%, transparent); fill: none; stroke: var(--dhs-group-good); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-group-brand span { display: grid; line-height: 1.2; }
  .dhs-group-brand b { font-size: 14.5px; font-weight: 720; letter-spacing: -0.01em; }
  .dhs-group-brand small { font-size: 11px; color: var(--dhs-group-muted); }
  .dhs-group-nav { display: grid; gap: 2px; }
  .dhs-group-nav button { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--dhs-group-muted); font-weight: 580; transition: background-color 160ms, color 160ms; }
  .dhs-group-nav button:hover { color: var(--dhs-group-ink); background: color-mix(in oklch, var(--dhs-group-ink) 5%, transparent); }
  .dhs-group-nav [aria-selected="true"] { color: var(--dhs-group-ink); background: var(--dhs-group-raise); }
  .dhs-group-nav svg { flex: none; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-group-nav [aria-selected="true"] svg { stroke: var(--dhs-group-accent); }
  .dhs-group-regions { display: grid; gap: 2px; }
  .dhs-group-regions .dhs-group-eyebrow { padding: 0 8px 4px; }
  .dhs-group-regions button { display: flex; justify-content: space-between; align-items: center; padding: 6px 10px; border-radius: 8px; font-size: 12.5px; color: var(--dhs-group-muted); text-align: left; transition: background-color 150ms, color 150ms; }
  .dhs-group-regions button:hover { color: var(--dhs-group-ink); background: color-mix(in oklch, var(--dhs-group-ink) 5%, transparent); }
  .dhs-group-regions [aria-checked="true"] { color: var(--dhs-group-ink); background: color-mix(in oklch, var(--dhs-group-accent) 13%, transparent); box-shadow: inset 2px 0 0 var(--dhs-group-accent); }
  .dhs-group-regions em { font: 500 11px var(--dhs-group-mono); font-style: normal; color: var(--dhs-group-faint); }
  .dhs-group-foot { margin-top: auto; padding: 0 6px; font-size: 11px; color: var(--dhs-group-faint); }

  /* ---------- main ---------- */
  .dhs-group-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }
  .dhs-group-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 18px; padding: 16px 18px 12px; }
  .dhs-group-title { display: grid; gap: 3px; }
  .dhs-group-title h2 { font-size: clamp(19px, 0.75rem + 1.25cqi, 26px); font-weight: 730; letter-spacing: -0.03em; line-height: 1.05; }
  .dhs-group-metrics { display: flex; flex-wrap: wrap; gap: 2px; padding: 3px; border-radius: 11px; background: var(--dhs-group-sunk); box-shadow: inset 0 0 0 1px var(--dhs-group-line); }
  .dhs-group-metrics button { height: 28px; padding: 0 11px; border-radius: 8px; font-size: 12px; font-weight: 620; color: var(--dhs-group-muted); transition: background-color 160ms, color 160ms; }
  .dhs-group-metrics button:hover { color: var(--dhs-group-ink); }
  .dhs-group-metrics [aria-checked="true"] { background: var(--dhs-group-ink); color: var(--dhs-group-bg); }
  .dhs-group-kpis { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 1px; margin: 0 18px 12px; border-radius: 12px; overflow: hidden; background: var(--dhs-group-line); box-shadow: 0 0 0 1px var(--dhs-group-line); }
  .dhs-group-kpis div { display: grid; gap: 1px; padding: 9px 12px; background: var(--dhs-group-card); min-width: 0; transition: background-color 200ms; }
  .dhs-group-kpis div[data-on] { background: color-mix(in oklch, var(--dhs-group-accent) 10%, var(--dhs-group-card)); box-shadow: inset 0 -2px 0 var(--dhs-group-accent); }
  .dhs-group-kpis dt { font-size: 11px; color: var(--dhs-group-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
