  { k: 'lfl', n: 'Like-for-like', hi: true, v: (x) => x.sales / x.ly - 1, f: (v) => (v >= 0 ? '+' : '−') + Math.abs(v * 100).toFixed(1) + '%' },
  { k: 'spend', n: 'Avg spend', hi: true, v: (x) => x.sales / x.covers, f: (v) => '£' + (v / 100).toFixed(2) },
  { k: 'lab', n: 'Labour', hi: false, v: (x) => (x.labour / x.sales) * 100, f: (v) => v.toFixed(1) + '%' },
  { k: 'gp', n: 'Gross profit', hi: true, v: (x) => (x.gpv / x.sales) * 100, f: (v) => v.toFixed(1) + '%' },
