        ' aria-selected="' + (openSite === id && w === W) + '" tabindex="' + ((cellFocus ? cellFocus === key : ri === 0 && w === W) ? 0 : -1) + '" style="--t:' + t.toFixed(3) + ';--d:' + (ri + w) + '" aria-label="' + SITES[id].n + ', week ' + WEEKS[w].no + ', ' + M().f(v) + '">' + M().f(v).replace('£', '') + '</span>';
