  $$('.dhs-group-scard', cards).forEach((b) => b.setAttribute('aria-pressed', String(+b.dataset.site === openSite)));
  $$('.dhs-group-gc', grid).forEach((c) => c.setAttribute('aria-selected', String(+c.dataset.site === openSite && +c.dataset.w === W)));
}
function renderDrawer() {
  if (openSite === null) return;
  const s = SITES[openSite], ids = vis();
  $('[data-d="sub"]', drawer).textContent = s.city + ' · ' + s.reg + ' · ' + s.seats + ' seats';
  $('[data-d="title"]', drawer).textContent = s.n;
  const R = ranks(W);
  $('[data-d="sum"]', drawer).textContent = 'General manager ' + s.mgr + '. Ranked ' + R[openSite] + ' of ' + ids.length + ' on ' + M().n.toLowerCase() + ' in week ' + WEEKS[W].no + ', with ' + F[openSite][W].covers.toLocaleString('en-GB') + ' covers.';
  $('[data-d="met"]', drawer).innerHTML = MET.map((m, i) => {
    const vals = WEEKS.map((_, w) => m.v(F[openSite][w])), sp = spark(vals, 84, 26), rk = ranks(W, m)[openSite];
    return '<li' + (i === mi ? ' data-cur' : '') + '><span>' + m.n + '<b>' + m.f(vals[W]) + '</b></span><svg class="dhs-group-spark" viewBox="0 0 84 26" aria-hidden="true"><path d="' + sp.d + '"/><circle cx="' + sp.last[0] + '" cy="' + sp.last[1] + '" r="2.4"/></svg><em>#' + rk + '</em></li>';
  }).join('');
}
drawer.addEventListener('click', (e) => {
  const b = e.target.closest('[data-act]'); if (!b) return;
  if (b.dataset.act === 'close') { const id = openSite; closeDrawer(); const t = $('tr[data-site="' + id + '"]', tbody); if (t && t.offsetParent) t.focus({ preventScroll: true }); return; }
  const order = Object.entries(ranks(W)).sort((a, c) => a[1] - c[1]).map((x) => +x[0]);
  const i = order.indexOf(openSite), n = order[(i + (b.dataset.act === 'next' ? 1 : order.length - 1)) % order.length];
  openDrawer(n);
  b.focus({ preventScroll: true });
});
drawer.addEventListener('keydown', (e) => { if (e.key === 'Escape') { e.preventDefault(); closeDrawer(); } });

/* ------------------------------------------------------------------ views */
const nav = $('.dhs-group-nav'), TITLES = { league: 'Site league', heat: 'Week by week', sites: 'Sites' };
function renderAll() {
  renderKpis();
  if (view === 'league') { renderBump(); renderTable(); }
  if (view === 'heat') renderHeat();
  if (view === 'sites') renderCards();
  renderDrawer();
  syncSel();
}
function go(v) {
  view = v;
  $$('button', nav).forEach((b) => { const me = b.dataset.view === v; b.setAttribute('aria-selected', String(me)); b.tabIndex = me ? 0 : -1; });
  $$('.dhs-group-pane').forEach((p) => { p.hidden = p.dataset.pane !== v; });
  $('[data-k="h"]').textContent = TITLES[v];
  hideTip(); hot = -1;
  renderAll();
}
nav.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) go(b.dataset.view); });
nav.addEventListener('keydown', (e) => {
  const k = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key]; if (!k) return;
  const bs = $$('button', nav), i = bs.indexOf(document.activeElement), n = bs[(i + k + bs.length) % bs.length];
  e.preventDefault(); n.focus(); go(n.dataset.view);
});
let rz = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (rz) return;
  rz = requestAnimationFrame(() => { rz = 0; if (root.isConnected && view === 'league') renderBump(); });
});
ro.observe(bump);

root.setAttribute('data-enter', '');
renderAll();
setTimeout(() => root.removeAttribute('data-enter'), 2000);

