@keyframes dhs-reviews-grow { from { scale: 0 1; } }
@keyframes dhs-reviews-growy { from { scale: 1 0; } }
@keyframes dhs-reviews-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dhs-reviews-toast { 0% { opacity: 0; translate: -50% 12px; } 12%, 85% { opacity: 1; translate: -50% 0; } 100% { opacity: 0; translate: -50% 6px; } }
@keyframes dhs-reviews-flash { from { background-color: color-mix(in oklch, var(--dhs-reviews-pos) 22%, var(--dhs-reviews-card)); } }

.dhs-reviews {
  /* re-theme with these four */
  --dhs-reviews-bg: oklch(0.965 0.014 88);
  --dhs-reviews-ink: oklch(0.21 0.012 60);
  --dhs-reviews-pos: oklch(0.56 0.11 135);
  --dhs-reviews-neg: oklch(0.6 0.18 32);
  /* derived */
  --dhs-reviews-card: color-mix(in oklch, var(--dhs-reviews-bg), white 60%);
  --dhs-reviews-rule: color-mix(in oklch, var(--dhs-reviews-ink) 82%, transparent);
  --dhs-reviews-line: color-mix(in oklch, var(--dhs-reviews-ink) 11%, transparent);
  --dhs-reviews-line2: color-mix(in oklch, var(--dhs-reviews-ink) 20%, transparent);
  --dhs-reviews-muted: color-mix(in oklch, var(--dhs-reviews-ink) 62%, var(--dhs-reviews-bg));
  --dhs-reviews-faint: color-mix(in oklch, var(--dhs-reviews-ink) 42%, var(--dhs-reviews-bg));
  --dhs-reviews-poshl: color-mix(in oklch, var(--dhs-reviews-pos) 24%, transparent);
  --dhs-reviews-neghl: color-mix(in oklch, var(--dhs-reviews-neg) 22%, transparent);
  --dhs-reviews-star: oklch(0.72 0.14 75);
  --dhs-reviews-serif: ui-serif, "Iowan Old Style", Georgia, serif;
  --dhs-reviews-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dhs-reviews-spring: linear(0, 0.03, 0.12 5%, 0.53 13%, 0.9 20%, 1.06 27%, 1.08 32%, 1.04 40%, 0.99 52%, 1);
  --dhs-reviews-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dhs-reviews-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhs-reviews-bg);
  color: var(--dhs-reviews-ink);
  font: 400 13px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dhs-reviews-ink);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dhs-reviews-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dhs-reviews-ink); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  /* phrase highlights from the CSS Custom Highlight API; names are document-global so they carry the prefix */
  & ::highlight(dhs-reviews-pos) { background-color: var(--dhs-reviews-poshl, oklch(0.56 0.11 135 / 0.24)); }
  & ::highlight(dhs-reviews-neg) { background-color: var(--dhs-reviews-neghl, oklch(0.6 0.18 32 / 0.22)); }
  & ::highlight(dhs-reviews-fpos) { background-color: var(--dhs-reviews-poshl, oklch(0.56 0.11 135 / 0.24)); text-decoration: underline 2px var(--dhs-reviews-pos, oklch(0.56 0.11 135)); text-underline-offset: 3px; }
  & ::highlight(dhs-reviews-fneg) { background-color: var(--dhs-reviews-neghl, oklch(0.6 0.18 32 / 0.22)); text-decoration: underline 2px var(--dhs-reviews-neg, oklch(0.6 0.18 32)); text-underline-offset: 3px; }
  .dhs-reviews-mk { color: inherit; border-radius: 2px; background: var(--dhs-reviews-poshl); }
  .dhs-reviews-mk[data-p="neg"] { background: var(--dhs-reviews-neghl); }

  .dhs-reviews-app { height: 100%; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }
  .dhs-reviews-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dhs-reviews-muted); }
  .dhs-reviews-note { font-size: 11.5px; color: var(--dhs-reviews-muted); font-variant-numeric: tabular-nums; }

  /* ---------- masthead ---------- */
  .dhs-reviews-mast { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px; padding: 14px 20px 12px; border-bottom: 3px double var(--dhs-reviews-rule); }
  .dhs-reviews-brand { display: flex; align-items: center; gap: 10px; margin-right: auto; }
  .dhs-reviews-brand svg { width: 30px; height: 30px; fill: none; stroke: var(--dhs-reviews-ink); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-reviews-brand span { display: grid; line-height: 1.1; }
  .dhs-reviews-brand b { font: 700 clamp(19px, 0.8rem + 1.2cqi, 25px)/1.05 var(--dhs-reviews-serif); letter-spacing: -0.015em; }
  .dhs-reviews-brand small { font-size: 10.5px; font-weight: 650; letter-spacing: 0.14em; text-transform: uppercase; color: var(--dhs-reviews-muted); margin-top: 3px; }
  .dhs-reviews-tabs { display: flex; gap: 4px; }
  .dhs-reviews-tabs button { position: relative; display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px; font-weight: 650; color: var(--dhs-reviews-muted); transition: color 160ms; }
  .dhs-reviews-tabs button::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: 0; height: 2px; background: var(--dhs-reviews-ink); scale: 0 1; transition: scale 280ms var(--dhs-reviews-ease); }
  .dhs-reviews-tabs button:hover { color: var(--dhs-reviews-ink); }
  .dhs-reviews-tabs [aria-selected="true"] { color: var(--dhs-reviews-ink); }
  .dhs-reviews-tabs [aria-selected="true"]::after { scale: 1 1; }
  .dhs-reviews-tabs em { min-width: 18px; padding: 0 5px; border-radius: 9px; font: 700 10.5px/18px var(--dhs-reviews-mono); font-style: normal; text-align: center; background: var(--dhs-reviews-neg); color: var(--dhs-reviews-card); }
  .dhs-reviews-tabs em:empty { display: none; }
  .dhs-reviews-range, .dhs-reviews-seg { display: inline-flex; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--dhs-reviews-ink) 7%, transparent); }
  .dhs-reviews-range button, .dhs-reviews-seg button { height: 27px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dhs-reviews-muted); transition: background-color 150ms, color 150ms; white-space: nowrap; }
  .dhs-reviews-range button:hover, .dhs-reviews-seg button:hover { color: var(--dhs-reviews-ink); }
  .dhs-reviews-range [aria-checked="true"], .dhs-reviews-seg [aria-checked="true"] { background: var(--dhs-reviews-card); color: var(--dhs-reviews-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--dhs-reviews-ink) 18%, transparent); }
  .dhs-reviews-small button { height: 24px; font-size: 11.5px; }

  /* ---------- kpis ---------- */
  .dhs-reviews-kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); padding: 0 20px; border-bottom: 1px solid var(--dhs-reviews-rule); }
  .dhs-reviews-kpis div { display: grid; gap: 2px; padding: 10px 14px 11px; border-left: 1px solid var(--dhs-reviews-line2); min-width: 0; }
  .dhs-reviews-kpis div:first-child { border-left: 0; padding-left: 0; }
  .dhs-reviews-kpis dt { font-size: 10.5px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dhs-reviews-muted); white-space: nowrap; }
  .dhs-reviews-kpis dd { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; }
  .dhs-reviews-kpis b { font: 700 clamp(19px, 0.6rem + 1.3cqi, 26px)/1.1 var(--dhs-reviews-serif); font-variant-numeric: tabular-nums lining-nums; letter-spacing: -0.02em; }
  .dhs-reviews-kpis small { font-size: 11px; color: var(--dhs-reviews-muted); font-variant-numeric: tabular-nums; }
  .dhs-reviews-kpis b[data-tone="neg"] { color: var(--dhs-reviews-neg); }
  .dhs-reviews-kpis b[data-tone="pos"] { color: var(--dhs-reviews-pos); }
  .dhs-reviews-stars { position: relative; display: inline-block; width: 74px; height: 14px; align-self: center; }
  .dhs-reviews-stars svg { position: absolute; inset: 0; width: 74px; height: 14px; }
  .dhs-reviews-stars svg path { fill: color-mix(in oklch, var(--dhs-reviews-ink) 13%, transparent); }
  .dhs-reviews-stars span { position: absolute; inset: 0 auto 0 0; width: calc(var(--v) * 100%); overflow: hidden; transition: width 600ms var(--dhs-reviews-ease); }
  .dhs-reviews-stars span path { fill: var(--dhs-reviews-star); }

  .dhs-reviews-pane { min-height: 0; }

  /* ---------- inbox ---------- */
  .dhs-reviews-inbox { display: grid; grid-template-columns: clamp(230px, 27cqi, 290px) minmax(0, 1fr); }
  .dhs-reviews-filters { min-height: 0; overflow: auto; display: grid; align-content: start; gap: 18px; padding: 14px 18px 16px 20px; border-right: 1px solid var(--dhs-reviews-line2); scrollbar-width: thin; scrollbar-color: var(--dhs-reviews-line2) transparent; }
  .dhs-reviews-block { display: grid; gap: 7px; }
  .dhs-reviews-dist { display: grid; gap: 2px; }
  .dhs-reviews-dist button { display: grid; grid-template-columns: 34px 1fr 26px; align-items: center; gap: 8px; padding: 3px 6px; border-radius: 6px; font-size: 12px; font-variant-numeric: tabular-nums; transition: background-color 150ms, opacity 150ms; }
  .dhs-reviews-dist button:hover { background: color-mix(in oklch, var(--dhs-reviews-ink) 6%, transparent); }
  .dhs-reviews-dist i { height: 8px; border-radius: 4px; background: var(--dhs-reviews-line); position: relative; overflow: hidden; }
  .dhs-reviews-dist i::after { content: ""; position: absolute; inset: 0 auto 0 0; width: calc(var(--v) * 100%); border-radius: 4px; background: var(--dhs-reviews-star); transition: width 500ms var(--dhs-reviews-ease); }
  .dhs-reviews-dist em { font-style: normal; text-align: right; color: var(--dhs-reviews-muted); }
  .dhs-reviews-dist:has([aria-pressed="true"]) button:not([aria-pressed="true"]) { opacity: 0.45; }
  .dhs-reviews-dist [aria-pressed="true"] { background: color-mix(in oklch, var(--dhs-reviews-star) 18%, transparent); }
  .dhs-reviews-aspects { display: grid; gap: 1px; }
  .dhs-reviews-asp { display: grid; grid-template-columns: 1fr 90px 30px; align-items: center; gap: 8px; padding: 4px 6px; border-radius: 6px; font-size: 12.5px; text-align: left; transition: background-color 150ms, opacity 150ms; }
  .dhs-reviews-asp:hover { background: color-mix(in oklch, var(--dhs-reviews-ink) 6%, transparent); }
  .dhs-reviews-aspects:has([aria-pressed="true"]) .dhs-reviews-asp:not([aria-pressed="true"]) { opacity: 0.45; }
  .dhs-reviews-asp[aria-pressed="true"] { background: color-mix(in oklch, var(--dhs-reviews-ink) 9%, transparent); font-weight: 650; }
  .dhs-reviews-div { position: relative; height: 10px; }
  .dhs-reviews-div::before { content: ""; position: absolute; left: 50%; top: -2px; bottom: -2px; width: 1px; background: var(--dhs-reviews-line2); }
  .dhs-reviews-div b, .dhs-reviews-div s { position: absolute; top: 1px; bottom: 1px; border-radius: 2px; transition: width 500ms var(--dhs-reviews-ease); }
  .dhs-reviews-div b { left: 50%; width: calc(var(--p) * 50%); background: var(--dhs-reviews-pos); }
  .dhs-reviews-div s { right: 50%; width: calc(var(--n) * 50%); background: var(--dhs-reviews-neg); }
  .dhs-reviews-asp em { font: 650 11px var(--dhs-reviews-mono); font-style: normal; text-align: right; font-variant-numeric: tabular-nums; }
  .dhs-reviews-asp em[data-neg] { color: var(--dhs-reviews-neg); }
  .dhs-reviews-sources { display: flex; flex-wrap: wrap; gap: 5px; }
  .dhs-reviews-chip { height: 26px; padding: 0 10px; border-radius: 99px; font-size: 11.5px; font-weight: 620; box-shadow: inset 0 0 0 1px var(--dhs-reviews-line2); color: var(--dhs-reviews-muted); transition: background-color 150ms, color 150ms; }
  .dhs-reviews-chip:hover { color: var(--dhs-reviews-ink); }
  .dhs-reviews-chip[aria-pressed="true"] { background: var(--dhs-reviews-ink); color: var(--dhs-reviews-card); box-shadow: none; }

  .dhs-reviews-feedcol { min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dhs-reviews-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 12px 20px 10px; border-bottom: 1px solid var(--dhs-reviews-line); }
  .dhs-reviews-switch { display: inline-flex; align-items: center; gap: 7px; height: 28px; font-size: 12px; font-weight: 600; color: var(--dhs-reviews-muted); }
  .dhs-reviews-switch i { position: relative; width: 28px; height: 16px; border-radius: 8px; background: color-mix(in oklch, var(--dhs-reviews-ink) 18%, transparent); transition: background-color 200ms; }
  .dhs-reviews-switch i::after { content: ""; position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--dhs-reviews-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--dhs-reviews-ink) 30%, transparent); transition: translate 260ms var(--dhs-reviews-spring); }
  .dhs-reviews-switch[aria-checked="true"] { color: var(--dhs-reviews-ink); }
  .dhs-reviews-switch[aria-checked="true"] i { background: var(--dhs-reviews-ink); }
  .dhs-reviews-switch[aria-checked="true"] i::after { translate: 12px 0; }
  .dhs-reviews-toolbar .dhs-reviews-note { margin-left: auto; }
  .dhs-reviews-clear { font-size: 12px; font-weight: 650; text-decoration: underline; text-underline-offset: 3px; }
  .dhs-reviews-feed { min-height: 0; overflow: auto; padding: 4px 20px 20px; scrollbar-width: thin; scrollbar-color: var(--dhs-reviews-line2) transparent; }
  .dhs-reviews-empty { padding: 40px 10px; text-align: center; font: italic 15px var(--dhs-reviews-serif); color: var(--dhs-reviews-muted); }

  .dhs-reviews-rev { position: relative; display: grid; grid-template-columns: 40px minmax(0, 1fr); gap: 4px 12px; padding: 16px 0 14px; border-bottom: 1px solid var(--dhs-reviews-line2); transition: opacity 260ms var(--dhs-reviews-ease), translate 360ms var(--dhs-reviews-ease), background-color 600ms; }
  @starting-style { .dhs-reviews-rev { opacity: 0; translate: 0 10px; } }
  .dhs-reviews-rev[data-flash] { animation: dhs-reviews-flash 1200ms var(--dhs-reviews-ease); }
  .dhs-reviews-av { grid-row: span 4; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; font: 700 15px var(--dhs-reviews-serif); background: color-mix(in oklch, var(--dhs-reviews-ink) 8%, var(--dhs-reviews-card)); box-shadow: inset 0 0 0 1px var(--dhs-reviews-line2); }
  .dhs-reviews-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 2px 10px; font-size: 11.5px; color: var(--dhs-reviews-muted); }
  .dhs-reviews-meta b { font-size: 12.5px; color: var(--dhs-reviews-ink); font-weight: 650; }
  .dhs-reviews-meta .dhs-reviews-stars { width: 64px; height: 12px; }
  .dhs-reviews-meta .dhs-reviews-stars svg { width: 64px; height: 12px; }
  .dhs-reviews-src { margin-left: auto; font-size: 10.5px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
  .dhs-reviews-rev h4 { font: 700 16px/1.25 var(--dhs-reviews-serif); letter-spacing: -0.005em; }
  .dhs-reviews-text { font: 400 14px/1.55 var(--dhs-reviews-serif); color: color-mix(in oklch, var(--dhs-reviews-ink) 88%, var(--dhs-reviews-bg)); max-width: 68ch; }
  .dhs-reviews-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; }
  .dhs-reviews-tag { display: inline-flex; align-items: center; gap: 4px; padding: 1px 7px; border-radius: 4px; font-size: 10.5px; font-weight: 650; letter-spacing: 0.03em; color: var(--dhs-reviews-pos); background: color-mix(in oklch, var(--dhs-reviews-pos) 11%, transparent); }
  .dhs-reviews-tag[data-p="neg"] { color: var(--dhs-reviews-neg); background: color-mix(in oklch, var(--dhs-reviews-neg) 10%, transparent); }
  .dhs-reviews-tag[data-route] { color: var(--dhs-reviews-ink); background: color-mix(in oklch, var(--dhs-reviews-ink) 9%, transparent); }
  .dhs-reviews-acts { grid-column: 2; position: relative; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 6px; }
  .dhs-reviews-btn { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px; border-radius: 8px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dhs-reviews-line2); transition: background-color 150ms, scale 200ms var(--dhs-reviews-spring); }
  .dhs-reviews-btn:hover { background: color-mix(in oklch, var(--dhs-reviews-ink) 6%, transparent); }
  .dhs-reviews-btn:active { scale: 0.96; }
  .dhs-reviews-btn svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-reviews-btn[aria-expanded="true"] { background: color-mix(in oklch, var(--dhs-reviews-ink) 9%, transparent); }
  .dhs-reviews-primary { background: var(--dhs-reviews-ink); color: var(--dhs-reviews-card); box-shadow: none; }
  .dhs-reviews-primary:hover { background: color-mix(in oklch, var(--dhs-reviews-ink), var(--dhs-reviews-bg) 18%); }
  .dhs-reviews-primary[aria-expanded="true"] { background: color-mix(in oklch, var(--dhs-reviews-ink), var(--dhs-reviews-bg) 30%); box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--dhs-reviews-ink) 60%, transparent); }
  .dhs-reviews-replied { font-size: 11.5px; font-weight: 600; color: var(--dhs-reviews-pos); display: inline-flex; align-items: center; gap: 5px; }
  .dhs-reviews-replied::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
  .dhs-reviews-await { font-size: 11.5px; font-weight: 650; color: var(--dhs-reviews-neg); }
  .dhs-reviews-reply { grid-column: 2; margin-top: 8px; padding: 9px 12px; border-left: 3px solid var(--dhs-reviews-ink); background: color-mix(in oklch, var(--dhs-reviews-ink) 4%, transparent); font-size: 12.5px; color: var(--dhs-reviews-muted); }
  .dhs-reviews-reply b { display: block; font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--dhs-reviews-ink); margin-bottom: 2px; }
  .dhs-reviews-compose { grid-column: 2; display: grid; grid-template-rows: 0fr; transition: grid-template-rows 380ms var(--dhs-reviews-ease); }
  .dhs-reviews-compose[data-open] { grid-template-rows: 1fr; }
  .dhs-reviews-compose > form { min-height: 0; overflow: hidden; display: grid; gap: 8px; }
  .dhs-reviews-compose[data-open] > form { padding-top: 10px; }
  .dhs-reviews-compose textarea { width: 100%; min-height: 96px; resize: vertical; padding: 10px 12px; border: 0; border-radius: 10px; font: 400 13px/1.5 system-ui, sans-serif; color: var(--dhs-reviews-ink); background: var(--dhs-reviews-card); box-shadow: inset 0 0 0 1px var(--dhs-reviews-line2); }
  .dhs-reviews-compose textarea:focus { outline: 2px solid var(--dhs-reviews-ink); outline-offset: 0; }
  .dhs-reviews-compose textarea[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--dhs-reviews-neg); }
  .dhs-reviews-compose .dhs-reviews-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
  .dhs-reviews-err { font-size: 11.5px; font-weight: 600; color: var(--dhs-reviews-neg); }
  .dhs-reviews-count { margin-left: auto; font: 500 11px var(--dhs-reviews-mono); color: var(--dhs-reviews-faint); }

  .dhs-reviews-menu { position: absolute; z-index: 6; top: calc(100% + 4px); left: var(--mx, 0); min-width: 200px; padding: 5px; border-radius: 11px; background: var(--dhs-reviews-card); box-shadow: 0 0 0 1px var(--dhs-reviews-line2), 0 14px 34px color-mix(in oklch, var(--dhs-reviews-ink) 22%, transparent); transform-origin: top left; transition: opacity 160ms, scale 200ms var(--dhs-reviews-ease); }
  @starting-style { .dhs-reviews-menu { opacity: 0; scale: 0.94; } }
  .dhs-reviews-menu[data-up] { top: auto; bottom: calc(100% + 4px); transform-origin: bottom left; }
  .dhs-reviews-menu button { display: grid; grid-template-columns: 16px 1fr; align-items: center; gap: 8px; width: 100%; padding: 7px 9px; border-radius: 7px; font-size: 12.5px; text-align: left; }
  .dhs-reviews-menu button:hover, .dhs-reviews-menu button:focus-visible { background: color-mix(in oklch, var(--dhs-reviews-ink) 7%, transparent); outline: none; }
  .dhs-reviews-menu button::before { content: ""; width: 7px; height: 7px; margin-left: 4px; border-radius: 50%; }
  .dhs-reviews-menu [aria-checked="true"]::before { background: var(--dhs-reviews-ink); }

  /* ---------- insights ---------- */
  .dhs-reviews-insights { overflow: auto; display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-rows: auto auto; grid-template-areas: "asp trend" "asp src"; padding: 14px 20px 18px; scrollbar-width: thin; scrollbar-color: var(--dhs-reviews-line2) transparent; }
  .dhs-reviews-card { min-width: 0; padding: 12px 14px; border-radius: 12px; background: var(--dhs-reviews-card); box-shadow: inset 0 0 0 1px var(--dhs-reviews-line2); }
  .dhs-reviews-cardhead { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; margin-bottom: 8px; }
  .dhs-reviews-cardhead h3 { font: 700 15px var(--dhs-reviews-serif); }
  .dhs-reviews-aspcard { grid-area: asp; }
  .dhs-reviews-trendcard { grid-area: trend; }
  .dhs-reviews-srccard { grid-area: src; padding: 6px; }
  .dhs-reviews-bigasp { display: grid; gap: 6px; }
  .dhs-reviews-bigasp li { display: grid; grid-template-columns: 112px minmax(0, 1fr) auto; align-items: center; gap: 10px; }
  .dhs-reviews-bigasp .dhs-reviews-name { font-size: 12.5px; font-weight: 650; }
  .dhs-reviews-bigbar { position: relative; height: 22px; }
  .dhs-reviews-bigbar::before { content: ""; position: absolute; left: 50%; top: -3px; bottom: -3px; width: 1px; background: var(--dhs-reviews-line2); }
  .dhs-reviews-bigbar b, .dhs-reviews-bigbar s { position: absolute; top: 0; bottom: 0; display: grid; align-items: center; font: 650 10.5px var(--dhs-reviews-mono); color: var(--dhs-reviews-card); text-decoration: none; transition: width 520ms var(--dhs-reviews-ease); animation: dhs-reviews-grow 620ms var(--dhs-reviews-ease) both; animation-delay: calc(var(--i) * 50ms); }
  .dhs-reviews-bigbar b { left: 50%; width: calc(var(--p) * 50%); padding-left: 6px; border-radius: 0 4px 4px 0; background: var(--dhs-reviews-pos); transform-origin: left; }
  .dhs-reviews-bigbar s { right: 50%; width: calc(var(--n) * 50%); padding-right: 6px; justify-items: end; border-radius: 4px 0 0 4px; background: var(--dhs-reviews-neg); transform-origin: right; }
  .dhs-reviews-bigasp .dhs-reviews-btn { height: 24px; padding: 0 8px; font-size: 11px; }
  .dhs-reviews-trend { position: relative; height: 210px; }
  .dhs-reviews-trend > svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dhs-reviews-trend svg {
    .dhs-reviews-gl { stroke: var(--dhs-reviews-line); }
    .dhs-reviews-gt { fill: var(--dhs-reviews-faint); font: 500 10px var(--dhs-reviews-mono); }
    .dhs-reviews-vol { fill: color-mix(in oklch, var(--dhs-reviews-ink) 14%, transparent); transform-box: fill-box; transform-origin: 50% 100%; animation: dhs-reviews-growy 560ms var(--dhs-reviews-ease) both; animation-delay: calc(var(--i) * 30ms); }
    .dhs-reviews-avgl { fill: none; stroke: var(--dhs-reviews-ink); stroke-width: 2.2; stroke-linejoin: round; stroke-dasharray: 1; animation: dhs-reviews-draw 1000ms var(--dhs-reviews-ease) both 200ms; }
    .dhs-reviews-avgd { fill: var(--dhs-reviews-card); stroke: var(--dhs-reviews-ink); stroke-width: 2; }
    .dhs-reviews-cross { stroke: var(--dhs-reviews-ink); stroke-opacity: 0.35; stroke-dasharray: 2 3; }
    .dhs-reviews-hit { fill: transparent; cursor: crosshair; }
  }
  .dhs-reviews-table { width: 100%; border-collapse: collapse; font-size: 12.5px; font-variant-numeric: tabular-nums; }
  .dhs-reviews-table th { text-align: left; padding: 8px 10px; font-size: 10.5px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dhs-reviews-muted); border-bottom: 1px solid var(--dhs-reviews-rule); }
  .dhs-reviews-table td { padding: 7px 10px; border-bottom: 1px solid var(--dhs-reviews-line); }
  .dhs-reviews-r, .dhs-reviews-table td.dhs-reviews-r { text-align: right; }

  .dhs-reviews-tip { position: absolute; z-index: 20; left: 0; top: 0; min-width: 150px; padding: 8px 10px; border-radius: 9px; background: var(--dhs-reviews-ink); color: var(--dhs-reviews-bg); font-size: 11.5px; pointer-events: none; font-variant-numeric: tabular-nums; }
  .dhs-reviews-tip b { display: block; margin-bottom: 3px; }
  .dhs-reviews-tip div { display: flex; justify-content: space-between; gap: 12px; color: color-mix(in oklch, var(--dhs-reviews-bg) 72%, var(--dhs-reviews-ink)); }
  .dhs-reviews-tip div span:last-child { color: var(--dhs-reviews-bg); font-weight: 600; }
  .dhs-reviews-toast { position: absolute; z-index: 30; left: 50%; bottom: 16px; translate: -50% 0; padding: 9px 14px; border-radius: 10px; background: var(--dhs-reviews-ink); color: var(--dhs-reviews-bg); font-weight: 600; font-size: 12.5px; opacity: 0; pointer-events: none; white-space: nowrap; }
  .dhs-reviews-toast[data-show] { animation: dhs-reviews-toast 2600ms var(--dhs-reviews-ease) both; }

  /* ---------- responsive ---------- */
  @container (max-width: 980px) {
    .dhs-reviews-kpis div:nth-child(3) { display: none; }
    .dhs-reviews-kpis { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .dhs-reviews-insights { grid-template-columns: minmax(0, 1fr); grid-template-areas: "asp" "trend" "src"; }
  }
  @container (max-width: 760px) {
    .dhs-reviews-app { display: block; overflow: auto; scrollbar-width: thin; }
    .dhs-reviews-mast { padding: 12px 14px 10px; }
    .dhs-reviews-kpis { padding: 0 14px; grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .dhs-reviews-kpis div { padding: 8px 0 9px 12px; border-top: 1px solid var(--dhs-reviews-line); }
    .dhs-reviews-kpis div:nth-child(odd) { border-left: 0; padding-left: 0; }
    .dhs-reviews-kpis div:nth-child(3) { display: grid; }
    .dhs-reviews-kpis div:nth-child(5) { grid-column: 1 / -1; border-left: 0; padding-left: 0; }
    .dhs-reviews-inbox { display: block; }
    .dhs-reviews-filters { overflow: visible; border-right: 0; border-bottom: 1px solid var(--dhs-reviews-line2); padding: 12px 14px; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
    .dhs-reviews-toolbar { padding: 10px 14px; }
    .dhs-reviews-feed { overflow: visible; padding: 0 14px 16px; }
    .dhs-reviews-insights { overflow: visible; padding: 12px 14px; }
  }
  @container (max-width: 480px) {
    .dhs-reviews-brand small { display: none; }
    .dhs-reviews-rev { grid-template-columns: minmax(0, 1fr); }
    .dhs-reviews-av { display: none; }
    .dhs-reviews-acts, .dhs-reviews-reply, .dhs-reviews-compose { grid-column: 1; }
    .dhs-reviews-src { margin-left: 0; }
    .dhs-reviews-bigasp li { grid-template-columns: 84px minmax(0, 1fr); }
    .dhs-reviews-bigasp .dhs-reviews-btn { display: none; }
  }

  @media (prefers-reduced-motion: reduce) {
    .dhs-reviews-bigbar b, .dhs-reviews-bigbar s, .dhs-reviews-trend svg .dhs-reviews-vol, .dhs-reviews-trend svg .dhs-reviews-avgl, .dhs-reviews-rev[data-flash] { animation: none; }
    .dhs-reviews-toast[data-show] { animation: none; opacity: 1; translate: -50% 0; }
    .dhs-reviews-rev, .dhs-reviews-compose, .dhs-reviews-menu, .dhs-reviews-switch i::after, .dhs-reviews-tabs button::after, .dhs-reviews-stars span, .dhs-reviews-dist i::after, .dhs-reviews-div b, .dhs-reviews-div s { transition-duration: 0ms; }
  }
}

