/* ------------------------------------------------------------------ data */
const ASPECTS = { room: 'Room', sleep: 'Sleep & noise', breakfast: 'Breakfast', staff: 'Staff', clean: 'Cleanliness', location: 'Location', value: 'Value', checkin: 'Check-in' };
const ROUTES = ['Front office', 'Housekeeping', 'Breakfast team', 'Maintenance', 'General manager'];
const RAW = [
  ['09-30', 'Ingrid B.', 'Couple', 5, 'Booking site', 'Quiet room above the courtyard', 'We asked for a quiet room and got one overlooking the courtyard. Slept brilliantly. Breakfast was the highlight, and the smoked haddock was perfect. Staff remembered our names by day two.',
