];
const END = new Date(2026, 9, 2);
const fmt = new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short' });
const REVIEWS = RAW.map(([md, name, stay, rating, source, title, text, ments, replied], id) => {
  const [m, d] = md.split('-').map(Number), date = new Date(2026, m - 1, d);
  const rv = { id, date, age: Math.round((END - date) / 864e5), name, stay, rating, source, title, text, ments, replied: !!replied, reply: '', route: null };
  if (rv.replied) rv.reply = suggest(rv);
  return rv;
});
const SOURCES = Array.from(new Set(REVIEWS.map((r) => r.source)));

function suggest(rv) {
  const first = rv.name.split(' ')[0];
