/* ------------------------------------------------------------------ data (prices net of VAT, pence) */
const CATS = [
  { k: 'starters', n: 'Starters', items: [
    ['Crab on toast', 'Crab toast', 1250, 460, 455], ['Burrata, blood orange', 'Burrata', 1100, 390, 390], ['Chicken liver parfait', 'Parfait', 900, 180, 520],
    ['Smoked eel, beetroot', 'Smoked eel', 1200, 490, 160], ['Soup of the day', 'Soup', 750, 110, 300], ['Scallops, cauliflower', 'Scallops', 1500, 640, 210],
    ['Heritage tomato salad', 'Tomatoes', 950, 230, 140], ['Cured trout, dill', 'Cured trout', 1150, 330, 250]] },
