    ['Brown butter tart', 'Tart', 850, 140, 380], ['Chocolate delice', 'Delice', 900, 190, 410], ['Buttermilk sorbet', 'Sorbet', 650, 90, 120],
    ['Cheese plate', 'Cheese', 1200, 480, 150], ['Poached quince', 'Quince', 800, 170, 90], ['Sticky toffee pudding', 'Toffee pudding', 850, 130, 470]] },
];
CATS.forEach((c) => { c.items = c.items.map(([n, short, price, cost, sold], i) => ({ id: c.k + i, n, short, price, cost, sold, planned: false })); });
const CLS = { star: ['Star', 'popular, profitable'], plow: ['Plowhorse', 'popular, thin margin'], puzz: ['Puzzle', 'profitable, slow seller'], dog: ['Dog', 'neither'] };
const ADVICE = {
  star: 'Keep it exactly where it is. Protect the recipe and portion, and give it the best spot on the card.',
  plow: 'Guests love it but it earns too little. Raise the price in small steps or re-cost the plate before touching the recipe.',
