const LOG = [
  { when: '14 Sep', id: 'desserts5', before: { price: 750, cost: 130, sold: 512 }, after: { price: 850, cost: 130, sold: 470 }, note: 'Price review', undone: false },
  { when: '7 Sep', id: 'mains2', before: { price: 2250, cost: 580, sold: 506 }, after: { price: 2250, cost: 520, sold: 506 }, note: 'Re-spec: thigh instead of breast', undone: false },
];

/* ------------------------------------------------------------------ analysis */
function analyse(items) {
  const n = items.length, total = items.reduce((a, it) => a + it.sold, 0);
  const tcm = items.reduce((a, it) => a + (it.price - it.cost) * it.sold, 0);
  const avgCM = tcm / total, thr = (1 / n) * 0.7;
