    const cm = it.price - it.cost, mm = it.sold / total;
    const hiP = mm >= thr, hiC = cm >= avgCM;
    return { it, id: it.id, n: it.n, short: it.short, price: it.price, cost: it.cost, sold: it.sold, cm, mm, tcm: cm * it.sold, fc: it.cost / it.price, cls: hiP ? (hiC ? 'star' : 'plow') : (hiC ? 'puzz' : 'dog') };
