}

/* ------------------------------------------------------------------ state */
let ci = 1, sel = null, draft = null, view = 'matrix', sort = { k: 'tcm', dir: -1 };
const show = { star: true, plow: true, puzz: true, dog: true };
const cat = () => CATS[ci];
function projected() {
  if (!draft) return cat().items;
  return cat().items.map((it) => it.id !== draft.id ? it : Object.assign({}, it, { price: draft.price, cost: draft.cost, sold: Math.max(0, Math.round(it.sold * Math.pow(draft.price / it.price, -draft.e))) }));
}
const changed = () => !!draft && (draft.price !== find(draft.id)[1].price || draft.cost !== find(draft.id)[1].cost);

/* ------------------------------------------------------------------ helpers */
const gbp = (p, dp) => (p < 0 ? '−' : '') + '£' + (Math.abs(p) / 100).toLocaleString('en-GB', { minimumFractionDigits: dp === undefined ? 2 : dp, maximumFractionDigits: dp === undefined ? 2 : dp });
const pc = (v) => (v * 100).toFixed(1) + '%';
function el(tag, attrs, parent) { const n = document.createElementNS(NS, tag); for (const k in attrs) n.setAttribute(k, attrs[k]); if (parent) parent.appendChild(n); return n; }
function toast(msg) { const t = $('.dhs-menu-toast'); t.textContent = msg; t.removeAttribute('data-show'); void t.offsetWidth; t.setAttribute('data-show', ''); }
const tip = $('.dhs-menu-tip');
function showTip(r, x, y) {
