  tip.innerHTML = '<b>' + r.n + '</b><div><span>Class</span><span>' + CLS[r.cls][0] + '</span></div><div><span>Price</span><span>' + gbp(r.price) + '</span></div><div><span>Margin</span><span>' + gbp(r.cm) + ' · food ' + pc(r.fc) + '</span></div><div><span>Sold, 4 weeks</span><span>' + r.sold + '</span></div><div><span>Menu mix</span><span>' + pc(r.mm) + '</span></div><div><span>Contribution</span><span>' + gbp(r.tcm, 0) + '</span></div>';
  tip.hidden = false;
  const R = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let lx = x - R.left + 16, ly = y - R.top - h - 12;
  if (lx + w > R.width - 8) lx = x - R.left - w - 16;
