const hideTip = () => { tip.hidden = true; };

/* ------------------------------------------------------------------ tabs, KPIs, class chips */
const cats = $('.dhs-menu-cats');
cats.innerHTML = CATS.map((c, i) => '<button type="button" role="tab" data-c="' + i + '" aria-selected="' + (i === ci) + '" tabindex="' + (i === ci ? 0 : -1) + '">' + c.n + '</button>').join('');
cats.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b && +b.dataset.c !== ci) setCat(+b.dataset.c); });
cats.addEventListener('keydown', (e) => {
  const k = { ArrowRight: 1, ArrowLeft: -1 }[e.key]; if (!k) return;
  const n = (ci + k + CATS.length) % CATS.length; e.preventDefault(); setCat(n); cats.children[n].focus();
});
function setCat(i) {
  ci = i; sel = null; draft = null; G = null;
  $$('button', cats).forEach((b) => { const me = +b.dataset.c === i; b.setAttribute('aria-selected', String(me)); b.tabIndex = me ? 0 : -1; });
  if (view !== 'matrix') go('matrix'); else render();
}
function renderKpis(A, A0) {
  const d = A.tcm - A0.tcm;
  $('.dhs-menu-kpis').innerHTML =
    '<div><dt>' + cat().n + ' revenue</dt><dd>' + gbp(A.rev, 0) + '</dd></div>' +
    '<div><dt>Contribution</dt><dd>' + gbp(A.tcm, 0) + (draft && d ? '<small' + (d < 0 ? ' data-neg' : '') + '>' + (d > 0 ? '+' : '') + gbp(d, 0) + '</small>' : '') + '</dd></div>' +
    '<div><dt>Average margin</dt><dd>' + gbp(A.avgCM) + '</dd></div>' +
    '<div><dt>Food cost</dt><dd>' + pc(A.fc) + '</dd></div>' +
    '<div><dt>Stars</dt><dd>' + A.rows.filter((r) => r.cls === 'star').length + ' of ' + A.rows.length + '</dd></div>';
}
const quads = $('.dhs-menu-quads');
function renderQuads(A) {
  quads.innerHTML = Object.keys(CLS).map((k) => '<button type="button" data-cls="' + k + '" aria-pressed="' + show[k] + '"><i></i><span><b>' + CLS[k][0] + '</b><small>' + CLS[k][1] + '</small></span><em>' + A.rows.filter((r) => r.cls === k).length + '</em></button>').join('');
}
quads.addEventListener('click', (e) => {
  const b = e.target.closest('button'); if (!b) return;
  show[b.dataset.cls] = !show[b.dataset.cls];
  render();
