/* ------------------------------------------------------------------ board */
const plot = $('.dhs-menu-plot'), svg = plot.querySelector('svg');
let G = null;
function renderBoard(A, A0) {
  const W = plot.clientWidth, H = plot.clientHeight;
  if (W < 80 || H < 80) return;
  const ml = 62, mr = 18, mt = 16, mb = 30;
  if (!G || G.W !== W || G.H !== H || G.ci !== ci || G.stale) {
    const cms = A0.rows.map((r) => r.cm), lo = Math.min(...cms), hi = Math.max(...cms), span = Math.max(100, hi - lo);
    const mmMax = Math.max(...A0.rows.map((r) => r.mm)) * 1.3, cmMax = hi + span * 0.5, cmMin = Math.max(0, lo - span * 0.7);
    svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H); svg.textContent = '';
    G = { W, H, ci, mmMax, cmMax, pts: {} };
    G.x = (v) => ml + Math.min(1.04, v / mmMax) * (W - ml - mr);
    G.y = (v) => H - mb - Math.min(1.04, Math.max(-0.02, (v - cmMin) / (cmMax - cmMin))) * (H - mt - mb);
    const bg = el('g', {}, svg);
    G.q = {};
