    el('text', { x: W - mr, y: H - 4, 'text-anchor': 'end', class: 'dhs-menu-axl' }, ax).textContent = 'Popularity · menu mix →';
    el('text', { x: ml + 4, y: mt - 4, class: 'dhs-menu-axl' }, ax).textContent = '↑ Margin per dish';
