    G.lab = {};
    [['puzz', ml + 10, mt + 18, 'start'], ['star', W - mr - 10, mt + 18, 'end'], ['dog', ml + 10, H - mb - 22, 'start'], ['plow', W - mr - 10, H - mb - 22, 'end']].forEach(([k, x, y, a]) => {
      el('text', { x, y, 'text-anchor': a, class: 'dhs-menu-qlab', 'data-cls': k }, labs).textContent = CLS[k][0] + 's';
      el('text', { x, y: y + 13, 'text-anchor': a, class: 'dhs-menu-qsub' }, labs).textContent = CLS[k][1];
    });
