@keyframes dhs-events-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes dhs-events-grow { from { scale: 1 0; } }
@keyframes dhs-events-growx { from { scale: 0 1; } }
@keyframes dhs-events-toast { 0% { opacity: 0; translate: -50% 12px; } 12%, 85% { opacity: 1; translate: -50% 0; } 100% { opacity: 0; translate: -50% 6px; } }
@keyframes dhs-events-shade { from { box-shadow: 0 0 0 transparent; } to { box-shadow: 10px 0 14px -10px oklch(0 0 0 / 0.7); } }
@keyframes dhs-events-land { 0% { box-shadow: 0 0 0 0 var(--stc); } 100% { box-shadow: 0 0 0 10px transparent; } }

.dhs-events {
  /* re-theme with these four */
  --dhs-events-bg: oklch(0.2 0.03 12);
  --dhs-events-ink: oklch(0.95 0.015 80);
  --dhs-events-accent: oklch(0.85 0.12 88);
  --dhs-events-lost: oklch(0.66 0.14 25);
  /* stage ramp: rose to gold */
  --dhs-events-s0: color-mix(in oklch, var(--dhs-events-ink) 42%, var(--dhs-events-bg));
  --dhs-events-s1: oklch(0.72 0.1 15);
  --dhs-events-s2: oklch(0.76 0.11 45);
  --dhs-events-s3: oklch(0.8 0.12 70);
  --dhs-events-s4: var(--dhs-events-accent);
  /* derived */
  --dhs-events-card: color-mix(in oklch, var(--dhs-events-bg), var(--dhs-events-ink) 5%);
  --dhs-events-raise: color-mix(in oklch, var(--dhs-events-bg), var(--dhs-events-ink) 11%);
  --dhs-events-sunk: color-mix(in oklch, var(--dhs-events-bg), black 30%);
  --dhs-events-line: color-mix(in oklch, var(--dhs-events-ink) 9%, transparent);
  --dhs-events-line2: color-mix(in oklch, var(--dhs-events-ink) 18%, transparent);
  --dhs-events-muted: color-mix(in oklch, var(--dhs-events-ink) 63%, var(--dhs-events-bg));
  --dhs-events-faint: color-mix(in oklch, var(--dhs-events-ink) 42%, var(--dhs-events-bg));
  --dhs-events-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dhs-events-spring: linear(0, 0.03, 0.12 5%, 0.53 13%, 0.9 20%, 1.06 27%, 1.08 32%, 1.04 40%, 0.99 52%, 1);
  --dhs-events-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dhs-events-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhs-events-bg);
  color: var(--dhs-events-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dhs-events-accent);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dhs-events-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  [data-stage="0"] { --stc: var(--dhs-events-s0); }
  [data-stage="1"] { --stc: var(--dhs-events-s1); }
  [data-stage="2"] { --stc: var(--dhs-events-s2); }
  [data-stage="3"] { --stc: var(--dhs-events-s3); }
  [data-stage="4"] { --stc: var(--dhs-events-s4); }

  .dhs-events-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dhs-events-muted); }
  .dhs-events-app { display: grid; height: 100%; grid-template-columns: 196px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dhs-events-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px 14px; background: var(--dhs-events-sunk); border-right: 1px solid var(--dhs-events-line); scrollbar-width: thin; scrollbar-color: var(--dhs-events-line2) transparent; }
  .dhs-events-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
  .dhs-events-brand svg { flex: none; width: 32px; height: 32px; padding: 5px; border-radius: 9px; background: color-mix(in oklch, var(--dhs-events-accent) 15%, transparent); fill: none; stroke: var(--dhs-events-accent); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-events-brand span { display: grid; line-height: 1.2; }
  .dhs-events-brand b { font-size: 14.5px; font-weight: 720; letter-spacing: 0.01em; }
  .dhs-events-brand small { font-size: 11px; color: var(--dhs-events-muted); }
  .dhs-events-nav { display: grid; gap: 2px; }
  .dhs-events-nav button { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--dhs-events-muted); font-weight: 580; transition: background-color 160ms, color 160ms; }
  .dhs-events-nav button:hover { color: var(--dhs-events-ink); background: var(--dhs-events-line); }
  .dhs-events-nav [aria-selected="true"] { color: var(--dhs-events-ink); background: var(--dhs-events-raise); }
  .dhs-events-nav svg { flex: none; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-events-nav [aria-selected="true"] svg { stroke: var(--dhs-events-accent); }
  .dhs-events-owners { display: grid; gap: 2px; }
  .dhs-events-owners .dhs-events-eyebrow, .dhs-events-types .dhs-events-eyebrow { padding: 0 8px 4px; }
  .dhs-events-owners button { display: grid; grid-template-columns: 22px 1fr auto; align-items: center; gap: 8px; padding: 5px 8px; border-radius: 8px; font-size: 12.5px; text-align: left; color: var(--dhs-events-muted); transition: background-color 150ms, color 150ms; }
  .dhs-events-owners button:hover { color: var(--dhs-events-ink); background: var(--dhs-events-line); }
  .dhs-events-owners [aria-checked="true"] { color: var(--dhs-events-ink); background: color-mix(in oklch, var(--dhs-events-accent) 12%, transparent); }
  .dhs-events-owners i { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; font: 700 9.5px system-ui, sans-serif; font-style: normal; background: var(--dhs-events-raise); color: var(--dhs-events-ink); }
  .dhs-events-owners em { font: 500 11px var(--dhs-events-mono); font-style: normal; color: var(--dhs-events-faint); }
  .dhs-events-types { display: grid; gap: 4px; }
  .dhs-events-chips { display: flex; flex-wrap: wrap; gap: 4px; padding: 0 4px; }
  .dhs-events-chips button { height: 25px; padding: 0 9px; border-radius: 99px; font-size: 11.5px; font-weight: 600; color: var(--dhs-events-muted); box-shadow: inset 0 0 0 1px var(--dhs-events-line2); transition: background-color 150ms, color 150ms; }
  .dhs-events-chips button:hover { color: var(--dhs-events-ink); }
  .dhs-events-chips [aria-pressed="true"] { background: var(--dhs-events-ink); color: var(--dhs-events-bg); box-shadow: none; }

  /* ---------- main ---------- */
  .dhs-events-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dhs-events-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 24px; padding: 16px 18px 12px; }
  .dhs-events-title { display: grid; gap: 3px; }
  .dhs-events-title h2 { font-size: clamp(19px, 0.75rem + 1.25cqi, 26px); font-weight: 720; letter-spacing: -0.025em; line-height: 1.05; }
  .dhs-events-kpis { display: flex; flex-wrap: wrap; gap: 6px 22px; }
  .dhs-events-kpis div { display: grid; gap: 1px; }
  .dhs-events-kpis dt { font-size: 11px; color: var(--dhs-events-muted); white-space: nowrap; }
  .dhs-events-kpis dd { font-size: 19px; font-weight: 720; letter-spacing: -0.02em; line-height: 1.15; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dhs-events-kpis dd small { margin-left: 4px; font-size: 11px; font-weight: 550; color: var(--dhs-events-faint); }
  .dhs-events-pane { min-height: 0; padding: 0 18px 16px; }

  /* ---------- pipeline ---------- */
  .dhs-events-pipe { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; }
  .dhs-events-funnel { display: flex; height: 30px; border-radius: 8px; overflow: hidden; gap: 2px; background: var(--dhs-events-sunk); }
  .dhs-events-funnel span { position: relative; display: flex; align-items: center; min-width: 0; padding: 0 8px; background: var(--stc); color: var(--dhs-events-bg); font: 650 11px var(--dhs-events-mono); white-space: nowrap; overflow: hidden; transform-origin: left; transition: flex-grow 600ms var(--dhs-events-ease); animation: dhs-events-growx 700ms var(--dhs-events-ease) both; animation-delay: calc(var(--i) * 70ms); }
  .dhs-events-funnel span[data-stage="0"] { color: var(--dhs-events-ink); }
  .dhs-events-board { min-height: 0; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; }
  .dhs-events-col { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-radius: 13px; background: var(--dhs-events-card); box-shadow: inset 0 0 0 1px var(--dhs-events-line), inset 0 3px 0 var(--stc); }
  .dhs-events-colhead { display: grid; gap: 2px; padding: 10px 11px 8px; border-bottom: 1px solid var(--dhs-events-line); }
  .dhs-events-colhead b { display: flex; justify-content: space-between; font-size: 12.5px; font-weight: 680; }
  .dhs-events-colhead b em { font: 600 11px var(--dhs-events-mono); font-style: normal; color: var(--dhs-events-muted); }
  .dhs-events-colhead span { font: 500 11px var(--dhs-events-mono); color: var(--dhs-events-muted); font-variant-numeric: tabular-nums; }
  .dhs-events-colhead span small { color: var(--dhs-events-faint); }
  .dhs-events-cards { min-height: 0; overflow: auto; display: grid; align-content: start; gap: 6px; padding: 8px; scrollbar-width: thin; scrollbar-color: var(--dhs-events-line2) transparent; }
  .dhs-events-lead { position: relative; display: grid; gap: 3px; width: 100%; padding: 8px 9px 8px 11px; border-radius: 9px; text-align: left; background: var(--dhs-events-raise); box-shadow: inset 2px 0 0 var(--stc); transition: background-color 150ms, translate 220ms var(--dhs-events-spring), box-shadow 200ms; animation: dhs-events-rise 420ms var(--dhs-events-ease) both; animation-delay: calc(var(--i) * 35ms); }
  .dhs-events-lead:hover { background: color-mix(in oklch, var(--dhs-events-raise), var(--dhs-events-ink) 6%); translate: 0 -1px; }
  .dhs-events-lead[aria-pressed="true"] { box-shadow: inset 2px 0 0 var(--stc), 0 0 0 1.5px var(--stc); }
  .dhs-events-lead[data-landed] { animation: dhs-events-land 900ms var(--dhs-events-ease); }
  .dhs-events-lead b { font-size: 12.5px; font-weight: 650; line-height: 1.25; }
  .dhs-events-lead span { font-size: 11px; color: var(--dhs-events-muted); }
  .dhs-events-lead strong { display: flex; justify-content: space-between; align-items: baseline; font: 650 12px var(--dhs-events-mono); font-variant-numeric: tabular-nums; }
  .dhs-events-lead strong i { font: 600 10px system-ui, sans-serif; font-style: normal; color: var(--dhs-events-faint); }
  .dhs-events-opt { position: absolute; top: 7px; right: 8px; padding: 0 5px; border-radius: 4px; font: 700 9.5px var(--dhs-events-mono); background: var(--dhs-events-lost); color: var(--dhs-events-bg); }
  .dhs-events-none { padding: 14px 6px; text-align: center; font-size: 11.5px; color: var(--dhs-events-faint); }

  /* ---------- diary ---------- */
  .dhs-events-diaryv { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 10px; }
  .dhs-events-diarybar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; }
  .dhs-events-diarybar h3 { min-width: 140px; text-align: center; font-size: 15px; font-weight: 700; }
  .dhs-events-step { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--dhs-events-line2); color: var(--dhs-events-muted); transition: background-color 150ms, color 150ms; }
  .dhs-events-step:hover:not(:disabled) { color: var(--dhs-events-ink); background: var(--dhs-events-line); }
  .dhs-events-step:disabled { opacity: 0.35; cursor: not-allowed; }
  .dhs-events-step svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-events-key { display: flex; flex-wrap: wrap; gap: 3px 12px; margin-left: auto; font-size: 11px; color: var(--dhs-events-muted); }
  .dhs-events-key li { display: flex; align-items: center; gap: 5px; }
  .dhs-events-key li::before { content: ""; width: 12px; height: 9px; border-radius: 2px; background: var(--stc); }
  .dhs-events-key li[data-stage="2"]::before { background: repeating-linear-gradient(-45deg, var(--stc) 0 2px, transparent 2px 4px); box-shadow: inset 0 0 0 1px var(--stc); }
  .dhs-events-key li[data-stage="1"]::before, .dhs-events-key li[data-stage="0"]::before { background: transparent; box-shadow: inset 0 0 0 1.5px var(--stc); }
  .dhs-events-key li[data-tgt]::before { height: 0; border-top: 2px dashed var(--dhs-events-ink); border-radius: 0; background: none; }
  .dhs-events-diary { min-height: 0; overflow: auto; border-radius: 13px; background: var(--dhs-events-card); box-shadow: inset 0 0 0 1px var(--dhs-events-line); scrollbar-width: thin; scrollbar-color: var(--dhs-events-line2) transparent; }
  .dhs-events-grid { --days: 31; display: grid; grid-template-columns: 112px repeat(var(--days), minmax(24px, 1fr)); grid-template-rows: 40px; grid-auto-rows: minmax(64px, 1fr); min-width: calc(112px + var(--days) * 24px); min-height: 100%; }
  .dhs-events-dh { position: sticky; top: 0; z-index: 2; display: grid; place-items: center; align-content: center; gap: 0; background: var(--dhs-events-card); border-bottom: 1px solid var(--dhs-events-line2); font: 600 10.5px var(--dhs-events-mono); color: var(--dhs-events-muted); line-height: 1.15; }
  .dhs-events-dh small { font: 600 8.5px system-ui, sans-serif; letter-spacing: 0.04em; color: var(--dhs-events-faint); }
  .dhs-events-dh[data-we] { color: var(--dhs-events-ink); }
  .dhs-events-dh[data-today] { color: var(--dhs-events-accent); }
  .dhs-events-sp { position: sticky; left: 0; z-index: 3; display: grid; align-content: center; gap: 1px; padding: 0 10px; background: var(--dhs-events-card); border-bottom: 1px solid var(--dhs-events-line); border-right: 1px solid var(--dhs-events-line2); }
  .dhs-events-sp b { font-size: 12.5px; font-weight: 650; }
  .dhs-events-sp small { font: 500 10.5px var(--dhs-events-mono); color: var(--dhs-events-faint); }
  .dhs-events-corner { position: sticky; left: 0; top: 0; z-index: 4; background: var(--dhs-events-card); border-bottom: 1px solid var(--dhs-events-line2); border-right: 1px solid var(--dhs-events-line2); }
  @supports (animation-timeline: scroll()) {
    /* the sticky space column casts a shadow only once the diary has scrolled sideways */
    .dhs-events-sp, .dhs-events-corner { animation: dhs-events-shade linear both; animation-timeline: scroll(nearest inline); animation-range: 0 40px; }
  }
  .dhs-events-cell { border-bottom: 1px solid var(--dhs-events-line); border-right: 1px solid color-mix(in oklch, var(--dhs-events-ink) 4%, transparent); }
  .dhs-events-cell[data-we] { background: color-mix(in oklch, var(--dhs-events-ink) 3%, transparent); }
  .dhs-events-cell[data-today] { background: color-mix(in oklch, var(--dhs-events-accent) 8%, transparent); }
  .dhs-events-blk {
    z-index: 1; align-self: stretch; margin: 6px 2px; padding: 4px 1px; border-radius: 6px; overflow: hidden; text-align: center; min-width: 0;
    background: var(--stc); color: var(--dhs-events-bg); font-size: 10px; font-weight: 650; line-height: 1.15;
    transition: scale 200ms var(--dhs-events-spring), box-shadow 160ms, opacity 200ms;
    animation: dhs-events-rise 420ms var(--dhs-events-ease) both; animation-delay: calc(var(--i) * 30ms);
  }
  .dhs-events-blk span { display: block; white-space: nowrap; overflow: hidden; text-overflow: clip; letter-spacing: -0.02em; }
  .dhs-events-blk small { display: block; font: 600 9px var(--dhs-events-mono); opacity: 0.8; }
  .dhs-events-blk[data-stage="2"] { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--stc) 55%, transparent) 0 4px, color-mix(in oklch, var(--stc) 22%, transparent) 4px 8px); box-shadow: inset 0 0 0 1.5px var(--stc); color: var(--dhs-events-ink); }
  .dhs-events-blk[data-stage="1"], .dhs-events-blk[data-stage="0"] { background: color-mix(in oklch, var(--stc) 10%, transparent); box-shadow: inset 0 0 0 1.5px var(--stc); color: var(--dhs-events-ink); border: 0; }
  .dhs-events-blk[data-stage="0"] { box-shadow: inset 0 0 0 1px var(--stc); }
  .dhs-events-blk[data-opt="1"] { align-self: start; height: calc(50% - 8px); margin-bottom: 0; }
  .dhs-events-blk[data-opt="2"] { align-self: end; height: calc(50% - 8px); margin-top: 0; outline: 1.5px dashed var(--dhs-events-lost); outline-offset: -1.5px; }
  .dhs-events-blk:hover { scale: 1.06; z-index: 2; box-shadow: 0 6px 16px oklch(0 0 0 / 0.45), inset 0 0 0 1.5px var(--dhs-events-ink); }
  .dhs-events-blk[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--dhs-events-ink); z-index: 2; }
  .dhs-events-clash { font-size: 11.5px; color: var(--dhs-events-muted); }
  .dhs-events-clash b { color: var(--dhs-events-lost); }

  /* ---------- forecast ---------- */
  .dhs-events-forev { overflow: auto; display: grid; gap: 12px; grid-template-rows: minmax(250px, 1fr) auto; scrollbar-width: thin; scrollbar-color: var(--dhs-events-line2) transparent; }
  .dhs-events-card { min-width: 0; border-radius: 13px; background: var(--dhs-events-card); box-shadow: inset 0 0 0 1px var(--dhs-events-line); padding: 12px 14px; }
  .dhs-events-cardhead { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 6px 12px; margin-bottom: 6px; }
  .dhs-events-cardhead h3 { font-size: 12.5px; font-weight: 690; }
  .dhs-events-cardhead .dhs-events-key { margin-left: 0; }
  .dhs-events-forecard { display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 250px; }
  .dhs-events-fchart { position: relative; min-height: 190px; }
  .dhs-events-fchart > svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dhs-events-fchart svg {
    .dhs-events-gl { stroke: var(--dhs-events-line); }
    .dhs-events-gt { fill: var(--dhs-events-faint); font: 500 10px var(--dhs-events-mono); }
    .dhs-events-mt { fill: var(--dhs-events-muted); font: 600 11px system-ui, sans-serif; }
    .dhs-events-seg { fill: var(--stc); transform-box: fill-box; transform-origin: 50% 100%; animation: dhs-events-grow 640ms var(--dhs-events-ease) both; animation-delay: calc(var(--i) * 60ms); }
    .dhs-events-seg[data-stage="2"] { fill: color-mix(in oklch, var(--stc) 70%, transparent); }
    .dhs-events-seg[data-stage="1"] { fill: color-mix(in oklch, var(--stc) 55%, transparent); }
    .dhs-events-seg[data-stage="0"] { fill: color-mix(in oklch, var(--stc) 60%, transparent); }
    .dhs-events-tgt { stroke: var(--dhs-events-ink); stroke-width: 2; stroke-dasharray: 5 4; }
    .dhs-events-hit { fill: transparent; cursor: crosshair; }
    .dhs-events-hit:hover { fill: color-mix(in oklch, var(--dhs-events-ink) 5%, transparent); }
  }
  .dhs-events-ftable { padding: 4px; }
  .dhs-events-table { width: 100%; border-collapse: collapse; font-size: 12.5px; font-variant-numeric: tabular-nums; }
  .dhs-events-table th { text-align: left; padding: 8px 10px; font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dhs-events-muted); border-bottom: 1px solid var(--dhs-events-line2); }
  .dhs-events-table td { padding: 7px 10px; border-bottom: 1px solid var(--dhs-events-line); }
  .dhs-events-r, .dhs-events-table td.dhs-events-r { text-align: right; }
  .dhs-events-pos { color: var(--dhs-events-accent); }
  .dhs-events-neg { color: var(--dhs-events-lost); }

  /* ---------- drawer ---------- */
  .dhs-events-drawer { position: absolute; z-index: 9; top: 10px; right: 10px; bottom: 10px; width: min(340px, calc(100% - 20px)); overflow: auto; display: grid; align-content: start; gap: 14px; padding: 16px; border-radius: 16px; background: color-mix(in oklch, var(--dhs-events-bg), var(--dhs-events-ink) 9%); box-shadow: 0 0 0 1px var(--dhs-events-line2), 0 30px 60px oklch(0 0 0 / 0.55); transition: translate 440ms var(--dhs-events-spring), opacity 220ms; scrollbar-width: thin; }
  @starting-style { .dhs-events-drawer { translate: 40px 0; opacity: 0; } }
  .dhs-events-drawer header { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
  .dhs-events-drawer h3 { font-size: 19px; font-weight: 730; letter-spacing: -0.02em; line-height: 1.2; outline: none; }
  .dhs-events-x { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; color: var(--dhs-events-muted); }
  .dhs-events-x:hover { color: var(--dhs-events-ink); background: var(--dhs-events-line); }
  .dhs-events-x svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  .dhs-events-stages { display: grid; grid-template-columns: repeat(5, 1fr); gap: 3px; }
  .dhs-events-stages li { display: grid; gap: 4px; font-size: 9.5px; font-weight: 650; letter-spacing: 0.03em; color: var(--dhs-events-faint); text-align: center; }
  .dhs-events-stages li::before { content: ""; height: 5px; border-radius: 3px; background: var(--dhs-events-line2); transition: background-color 300ms; }
  .dhs-events-stages li[data-done]::before { background: var(--stc); }
  .dhs-events-stages li[data-cur] { color: var(--dhs-events-ink); }
  .dhs-events-stages[data-lost] li::before { background: color-mix(in oklch, var(--dhs-events-lost) 40%, transparent); }
  .dhs-events-dl { display: grid; grid-template-columns: auto 1fr; gap: 5px 14px; font-size: 12.5px; }
  .dhs-events-dl dt { color: var(--dhs-events-muted); }
  .dhs-events-dl dd { text-align: right; font-variant-numeric: tabular-nums; }
  .dhs-events-dl dd[data-warn] { color: var(--dhs-events-lost); font-weight: 650; }
  .dhs-events-acts { display: grid; gap: 6px; }
  .dhs-events-btn { height: 36px; border-radius: 10px; font-weight: 650; font-size: 12.5px; background: var(--dhs-events-raise); box-shadow: inset 0 0 0 1px var(--dhs-events-line2); transition: background-color 150ms, scale 200ms var(--dhs-events-spring); }
  .dhs-events-btn:hover { background: color-mix(in oklch, var(--dhs-events-raise), var(--dhs-events-ink) 7%); }
  .dhs-events-btn:active { scale: 0.97; }
  .dhs-events-primary { background: var(--dhs-events-accent); color: var(--dhs-events-bg); box-shadow: none; }
  .dhs-events-primary:hover { background: color-mix(in oklch, var(--dhs-events-accent), white 15%); }
  .dhs-events-danger { color: var(--dhs-events-lost); }
  .dhs-events-assign { display: grid; gap: 7px; padding-top: 12px; border-top: 1px solid var(--dhs-events-line); }
  .dhs-events-who { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; }
  .dhs-events-who button { padding: 7px 4px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--dhs-events-muted); box-shadow: inset 0 0 0 1px var(--dhs-events-line2); transition: background-color 150ms, color 150ms; }
  .dhs-events-who [aria-checked="true"] { color: var(--dhs-events-bg); background: var(--dhs-events-ink); box-shadow: none; }

  .dhs-events-tip { position: absolute; z-index: 20; left: 0; top: 0; min-width: 170px; padding: 8px 10px; border-radius: 10px; background: color-mix(in oklch, var(--dhs-events-bg), var(--dhs-events-ink) 14%); box-shadow: 0 0 0 1px var(--dhs-events-line2), 0 14px 30px oklch(0 0 0 / 0.45); font-size: 11.5px; pointer-events: none; font-variant-numeric: tabular-nums; }
  .dhs-events-tip b { display: block; margin-bottom: 3px; font-size: 12px; }
  .dhs-events-tip div { display: flex; justify-content: space-between; gap: 14px; color: var(--dhs-events-muted); }
  .dhs-events-tip div span:last-child { color: var(--dhs-events-ink); font-weight: 600; }
