    const [yy, mm] = MONTHS[a.k], gap = a.wtd - a.tgt;
    return '<tr><td>' + fmtM.format(new Date(yy, mm, 1)) + '</td><td class="dhs-events-r">' + a.ls.length + '</td><td class="dhs-events-r">' + gbp(a.def) + '</td><td class="dhs-events-r">' + gbp(a.wtd) + '</td><td class="dhs-events-r">' + gbp(a.tgt) + '</td><td class="dhs-events-r ' + (gap >= 0 ? 'dhs-events-pos' : 'dhs-events-neg') + '">' + (gap >= 0 ? '+' : '−') + gbp(Math.abs(gap)) + '</td></tr>';
  }).join('');
}

/* ------------------------------------------------------------------ drawer */
const drawer = $('.dhs-events-drawer');
function toggle(id) { if (open === id) close(); else openLead(id); }
function openLead(id) { open = id; renderDrawer(); syncSel(); $('[data-d="title"]', drawer).focus({ preventScroll: true }); }
function close() { const id = open; open = null; drawer.hidden = true; syncSel(); const c = $('[data-id="' + id + '"]'); if (c && c.offsetParent) c.focus({ preventScroll: true }); }
function syncSel() { $$('.dhs-events-lead, .dhs-events-blk').forEach((c) => c.setAttribute('aria-pressed', String(+c.dataset.id === open))); }
function renderDrawer() {
  const l = LEADS[open]; if (!l) { drawer.hidden = true; return; }
  drawer.hidden = false;
  const opt = options();
  $('[data-d="sub"]', drawer).textContent = l.type + ' · ' + SPACES[l.space][0];
  $('[data-d="title"]', drawer).textContent = l.n;
  const st = $('[data-d="stages"]', drawer);
  st.toggleAttribute('data-lost', l.lost);
  st.innerHTML = STAGES.map((s, i) => '<li data-stage="' + i + '"' + (i <= l.stage && !l.lost ? ' data-done' : '') + (i === l.stage ? ' data-cur aria-current="step"' : '') + '>' + s[0] + '</li>').join('');
  const over = l.guests > SPACES[l.space][1];
  $('[data-d="facts"]', drawer).innerHTML = '<dt>Date</dt><dd>' + fmtD.format(l.date) + ' ' + l.date.getFullYear() + '</dd><dt>Guests</dt><dd' + (over ? ' data-warn' : '') + '>' + l.guests + ' of ' + SPACES[l.space][1] + ' max</dd>' +
    '<dt>Food &amp; drink</dt><dd>' + l.guests + ' × £' + l.fb + ' = ' + gbp(l.guests * l.fb * 100) + '</dd><dt>Room hire</dt><dd>' + gbp(l.hire * 100) + '</dd><dt>Event value</dt><dd><b>' + gbp(l.value) + '</b></dd>' +
    '<dt>Weighted</dt><dd>' + (l.lost ? 'lost' : Math.round(STAGES[l.stage][1] * 100) + '% → ' + gbp(l.value * STAGES[l.stage][1])) + '</dd>' +
    (opt[l.id] ? '<dt>Hold</dt><dd' + (opt[l.id] === 2 ? ' data-warn' : '') + '>' + (opt[l.id] === 1 ? '1st option on this space' : '2nd option, behind another hold') + '</dd>' : '');
  const next = STAGES[l.stage + 1];
  $('[data-d="acts"]', drawer).innerHTML = l.lost ? '<button type="button" class="dhs-events-btn dhs-events-primary" data-do="reopen">Reopen as an enquiry</button>' :
    (next ? '<button type="button" class="dhs-events-btn dhs-events-primary" data-do="adv">Move to ' + next[0].toLowerCase() + '</button>' : '<button type="button" class="dhs-events-btn" data-do="brief">Send the function sheet to the kitchen</button>') +
    (l.stage > 0 ? '<button type="button" class="dhs-events-btn" data-do="back">Back to ' + STAGES[l.stage - 1][0].toLowerCase() + '</button>' : '') +
    '<button type="button" class="dhs-events-btn dhs-events-danger" data-do="lose">Mark as lost</button>';
  $('[data-d="who"]', drawer).innerHTML = OWNERS.map((o, i) => '<button type="button" role="radio" data-o="' + i + '" aria-checked="' + (l.owner === i) + '" tabindex="' + (l.owner === i ? 0 : -1) + '">' + o[0].split(' ')[0] + '</button>').join('');
}
drawer.addEventListener('click', (e) => {
  const l = LEADS[open]; if (!l) return;
  if (e.target.closest('[data-act="close"]')) { close(); return; }
  const w = e.target.closest('[data-d="who"] button');
  if (w) { l.owner = +w.dataset.o; render(); toast(l.n + ' is now with ' + OWNERS[l.owner][0]); return; }
  const b = e.target.closest('[data-do]'); if (!b) return;
  const d = b.dataset.do, from = l.stage;
  if (d === 'brief') { toast('Function sheet for ' + l.n + ' sent to the kitchen and banqueting team'); b.textContent = 'Function sheet sent'; return; }
  const first = new Map($$('.dhs-events-lead', board).map((c) => [c.dataset.id, c.getBoundingClientRect()]));
  if (d === 'adv') l.stage++;
  if (d === 'back') l.stage--;
  if (d === 'lose') l.lost = true;
  if (d === 'reopen') { l.lost = false; l.stage = 0; }
  render();
  /* the moved card flies from its old column to its new one */
  const card = $('.dhs-events-lead[data-id="' + l.id + '"]', board), f = first.get(String(l.id));
  if (card && f && !RM.matches) {
    const n = card.getBoundingClientRect();
    card.animate([{ transform: 'translate(' + (f.left - n.left) + 'px,' + (f.top - n.top) + 'px) scale(1.04)', boxShadow: '0 18px 40px oklch(0 0 0 / 0.5)' }, { transform: 'none', boxShadow: '0 0 0 transparent' }], { duration: 620, easing: 'cubic-bezier(0.2, 0.85, 0.25, 1)' });
    card.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  }
  if (card) { card.removeAttribute('data-landed'); void card.offsetWidth; card.setAttribute('data-landed', ''); }
  toast(d === 'lose' ? l.n + ' marked as lost' : d === 'reopen' ? l.n + ' reopened as an enquiry' : l.n + ': ' + STAGES[from][0] + ' → ' + STAGES[l.stage][0]);
  const nb = $('[data-do]', drawer); if (nb) nb.focus({ preventScroll: true });
});
drawer.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') { e.preventDefault(); close(); return; }
  const w = e.target.closest('[data-d="who"] button');
  const k = { ArrowRight: 1, ArrowLeft: -1 }[e.key];
  if (w && k) { const bs = $$('[data-d="who"] button', drawer), n = bs[(bs.indexOf(w) + k + bs.length) % bs.length]; e.preventDefault(); n.click(); const m = $('[data-d="who"] [aria-checked="true"]', drawer); if (m) m.focus(); }
});

/* ------------------------------------------------------------------ views */
const nav = $('.dhs-events-nav'), TITLES = { pipe: 'Event pipeline', diary: 'Space diary', fore: 'Forecast' };
function render() {
  renderKpis();
  if (view === 'pipe') renderPipe();
  if (view === 'diary') renderDiary();
  if (view === 'fore') renderFore();
  if (open !== null) { if (!pass(LEADS[open])) close(); else renderDrawer(); }
  syncSel();
}
function go(v) {
  view = v;
  $$('button', nav).forEach((b) => { const me = b.dataset.view === v; b.setAttribute('aria-selected', String(me)); b.tabIndex = me ? 0 : -1; });
  $$('.dhs-events-pane').forEach((p) => { p.hidden = p.dataset.pane !== v; });
  $('[data-k="h"]').textContent = TITLES[v];
  hideTip();
  render();
}
nav.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) go(b.dataset.view); });
nav.addEventListener('keydown', (e) => {
  const k = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key]; if (!k) return;
  const bs = $$('button', nav), i = bs.indexOf(document.activeElement), n = bs[(i + k + bs.length) % bs.length];
  e.preventDefault(); n.focus(); go(n.dataset.view);
});
let rz = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (rz) return;
  rz = requestAnimationFrame(() => { rz = 0; if (root.isConnected && view === 'fore') renderFore(); });
});
ro.observe(fchart);

render();

css:
@keyframes dhs-spend-in { from { opacity: 0; scale: 0.92; } }
@keyframes dhs-spend-rise { from { opacity: 0; translate: 0 8px; } }
@keyframes dhs-spend-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dhs-spend-toast { 0% { opacity: 0; translate: -50% 12px; } 12%, 85% { opacity: 1; translate: -50% 0; } 100% { opacity: 0; translate: -50% 6px; } }

@property --dhs-spend-sheen { syntax: "<percentage>"; inherits: false; initial-value: -30%; }

.dhs-spend {
  /* re-theme with these four */
  --dhs-spend-bg: oklch(0.966 0.005 250);
  --dhs-spend-ink: oklch(0.22 0.02 255);
  --dhs-spend-accent: oklch(0.6 0.13 50);
  --dhs-spend-up: oklch(0.58 0.17 28);
  --dhs-spend-down: oklch(0.56 0.12 160);
  /* categories, earthy and distinct */
  --dhs-spend-c0: oklch(0.66 0.13 140);
  --dhs-spend-c1: oklch(0.58 0.15 25);
  --dhs-spend-c2: oklch(0.6 0.1 230);
  --dhs-spend-c3: oklch(0.83 0.1 92);
  --dhs-spend-c4: oklch(0.7 0.08 70);
  --dhs-spend-c5: oklch(0.47 0.12 355);
  --dhs-spend-c6: oklch(0.66 0.12 48);
  --dhs-spend-c7: oklch(0.7 0.02 255);
  /* derived */
  --dhs-spend-card: color-mix(in oklch, var(--dhs-spend-bg), white 82%);
  --dhs-spend-line: color-mix(in oklch, var(--dhs-spend-ink) 10%, transparent);
  --dhs-spend-line2: color-mix(in oklch, var(--dhs-spend-ink) 19%, transparent);
  --dhs-spend-muted: color-mix(in oklch, var(--dhs-spend-ink) 62%, var(--dhs-spend-bg));
  --dhs-spend-faint: color-mix(in oklch, var(--dhs-spend-ink) 42%, var(--dhs-spend-bg));
  --dhs-spend-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dhs-spend-spring: linear(0, 0.03, 0.12 5%, 0.53 13%, 0.9 20%, 1.06 27%, 1.08 32%, 1.04 40%, 0.99 52%, 1);
  --dhs-spend-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dhs-spend-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dhs-spend-bg);
  color: var(--dhs-spend-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dhs-spend-accent);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dhs-spend-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dhs-spend-ink); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  [data-cat="0"] { --tc: var(--dhs-spend-c0); }
  [data-cat="1"] { --tc: var(--dhs-spend-c1); }
  [data-cat="2"] { --tc: var(--dhs-spend-c2); }
  [data-cat="3"] { --tc: var(--dhs-spend-c3); }
  [data-cat="4"] { --tc: var(--dhs-spend-c4); }
  [data-cat="5"] { --tc: var(--dhs-spend-c5); }
  [data-cat="6"] { --tc: var(--dhs-spend-c6); }
  [data-cat="7"] { --tc: var(--dhs-spend-c7); }

  .dhs-spend-note { font-size: 11.5px; color: var(--dhs-spend-muted); font-variant-numeric: tabular-nums; }
  .dhs-spend-app { height: 100%; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }

  /* ---------- top ---------- */
  .dhs-spend-top { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 20px; padding: 14px 18px 0; }
  .dhs-spend-brand { display: flex; align-items: center; gap: 10px; margin-right: auto; }
  .dhs-spend-brand svg { width: 34px; height: 34px; padding: 6px; border-radius: 10px; background: var(--dhs-spend-ink); fill: none; stroke: var(--dhs-spend-card); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dhs-spend-brand span { display: grid; line-height: 1.15; }
  .dhs-spend-brand b { font-size: clamp(16px, 0.6rem + 1cqi, 20px); font-weight: 760; letter-spacing: -0.025em; }
  .dhs-spend-brand small { font-size: 11px; color: var(--dhs-spend-muted); }
  .dhs-spend-tabs { display: flex; gap: 2px; padding: 3px; border-radius: 11px; background: color-mix(in oklch, var(--dhs-spend-ink) 6%, transparent); }
  .dhs-spend-tabs button { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 14px; border-radius: 8px; font-weight: 640; font-size: 12.5px; color: var(--dhs-spend-muted); transition: background-color 160ms, color 160ms; }
  .dhs-spend-tabs button:hover { color: var(--dhs-spend-ink); }
  .dhs-spend-tabs [aria-selected="true"] { background: var(--dhs-spend-card); color: var(--dhs-spend-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--dhs-spend-ink) 15%, transparent); }
  .dhs-spend-tabs em { min-width: 18px; padding: 0 5px; border-radius: 9px; font: 700 10.5px/18px var(--dhs-spend-mono); font-style: normal; text-align: center; background: var(--dhs-spend-accent); color: var(--dhs-spend-card); }
  .dhs-spend-tabs em:empty { display: none; }
  .dhs-spend-range, .dhs-spend-seg { display: inline-flex; padding: 3px; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--dhs-spend-line2); }
  .dhs-spend-range button, .dhs-spend-seg button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dhs-spend-muted); transition: background-color 150ms, color 150ms; white-space: nowrap; }
  .dhs-spend-range button:hover, .dhs-spend-seg button:hover { color: var(--dhs-spend-ink); }
  .dhs-spend-range [aria-checked="true"], .dhs-spend-seg [aria-checked="true"] { background: var(--dhs-spend-ink); color: var(--dhs-spend-card); }
  .dhs-spend-small button { height: 22px; font-size: 11px; padding: 0 8px; }

  .dhs-spend-kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; padding: 12px 18px; }
  .dhs-spend-kpis div { display: grid; gap: 1px; padding: 9px 12px; border-radius: 11px; background: var(--dhs-spend-card); box-shadow: 0 0 0 1px var(--dhs-spend-line); min-width: 0; }
  .dhs-spend-kpis dt { font-size: 11px; color: var(--dhs-spend-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhs-spend-kpis dd { font: 700 clamp(16px, 0.55rem + 1.05cqi, 21px)/1.2 var(--dhs-spend-mono); letter-spacing: -0.03em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dhs-spend-kpis dd small { margin-left: 4px; font: 500 11px system-ui, sans-serif; letter-spacing: 0; color: var(--dhs-spend-faint); }
  .dhs-spend-kpis dd[data-tone="up"] { color: var(--dhs-spend-up); }
  .dhs-spend-kpis dd[data-tone="down"] { color: var(--dhs-spend-down); }
  .dhs-spend-pane { min-height: 0; padding: 0 18px 16px; }

  /* ---------- map ---------- */
  .dhs-spend-mapv { display: grid; grid-template-columns: minmax(0, 1fr) clamp(262px, 30cqi, 330px); gap: 12px; }
  .dhs-spend-mapcard { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 8px; padding: 12px; border-radius: 14px; background: var(--dhs-spend-card); box-shadow: 0 0 0 1px var(--dhs-spend-line); }
  .dhs-spend-maphead { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 10px; }
  .dhs-spend-crumbs { display: flex; align-items: center; gap: 4px; font-size: 13px; font-weight: 650; }
  .dhs-spend-crumbs button { padding: 3px 7px; border-radius: 6px; color: var(--dhs-spend-muted); text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--dhs-spend-line2); }
  .dhs-spend-crumbs button:hover { color: var(--dhs-spend-ink); background: var(--dhs-spend-line); }
  .dhs-spend-crumbs span[aria-current] { padding: 3px 7px; }
  .dhs-spend-crumbs i { color: var(--dhs-spend-faint); font-style: normal; }
  .dhs-spend-tree { position: relative; min-height: 220px; overflow: hidden; border-radius: 9px; }
  .dhs-spend-layer { position: absolute; inset: 0; transform-origin: 0 0; }
  .dhs-spend-tile {
    --tc2: color-mix(in oklch, var(--tc), white calc(var(--k, 0) * 26%));
    position: absolute; display: grid; align-content: space-between; padding: 8px 9px; overflow: hidden; text-align: left;
    border: 2px solid var(--dhs-spend-card); border-radius: 9px;
    background:
      linear-gradient(105deg, transparent calc(var(--dhs-spend-sheen) - 18%), color-mix(in oklch, white 30%, transparent) var(--dhs-spend-sheen), transparent calc(var(--dhs-spend-sheen) + 18%)),
      var(--tc2);
    color: color-mix(in oklch, var(--dhs-spend-ink) 92%, transparent);
    transition: --dhs-spend-sheen 700ms var(--dhs-spend-ease), filter 160ms, box-shadow 160ms, opacity 200ms;
    animation: dhs-spend-in 520ms var(--dhs-spend-ease) both; animation-delay: calc(var(--i) * 28ms);
  }
  .dhs-spend-tile[data-dark] { color: var(--dhs-spend-card); }
  .dhs-spend-tile:hover { --dhs-spend-sheen: 130%; filter: saturate(1.15) brightness(1.03); box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--dhs-spend-ink) 70%, transparent); z-index: 1; }
  .dhs-spend-tile[aria-pressed="true"] { box-shadow: inset 0 0 0 3px var(--dhs-spend-ink); z-index: 2; }
  .dhs-spend-tile b { display: block; font-size: 12.5px; font-weight: 700; line-height: 1.15; letter-spacing: -0.005em; }
  .dhs-spend-tile small { display: block; font-size: 10.5px; opacity: 0.8; }
  .dhs-spend-tile strong { font: 700 clamp(12px, 0.45rem + 0.9cqi, 17px) var(--dhs-spend-mono); letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
  .dhs-spend-tile em { font: 600 10.5px var(--dhs-spend-mono); font-style: normal; opacity: 0.85; margin-left: 5px; }
  .dhs-spend-tile[data-size="s"] { padding: 4px 6px; }
  .dhs-spend-tile[data-size="s"] small, .dhs-spend-tile[data-size="s"] em { display: none; }
  .dhs-spend-tile[data-size="s"] strong { font-size: 11px; }
  .dhs-spend-tile[data-size="s"] b { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dhs-spend-tile[data-size="s"] > span { min-width: 0; }
  .dhs-spend-tile[data-size="xs"] > * { display: none; }
  .dhs-spend-tree[data-mode="chg"] .dhs-spend-tile { --tc2: color-mix(in oklab, var(--chg) calc(var(--t) * 80%), color-mix(in oklch, var(--dhs-spend-bg), white 40%)); color: var(--dhs-spend-ink); }
  .dhs-spend-tree[data-mode="chg"] .dhs-spend-tile[data-dark] { color: var(--dhs-spend-card); }
  .dhs-spend-legend { font-size: 11px; color: var(--dhs-spend-faint); }

  /* ---------- price watch ---------- */
  .dhs-spend-watch { min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 8px; padding: 12px; border-radius: 14px; background: var(--dhs-spend-card); box-shadow: 0 0 0 1px var(--dhs-spend-line); }
  .dhs-spend-watchhead { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
  .dhs-spend-watchhead h3 { font-size: 14px; font-weight: 720; }
  .dhs-spend-filter { display: flex; }
  .dhs-spend-filter button { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 6px 0 10px; border-radius: 99px; font-size: 11.5px; font-weight: 650; background: var(--tc); color: var(--dhs-spend-card); }
  .dhs-spend-filter button svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }
  .dhs-spend-items { min-height: 0; overflow: auto; display: grid; align-content: start; gap: 4px; margin: 0 -4px; padding: 0 4px; scrollbar-width: thin; scrollbar-color: var(--dhs-spend-line2) transparent; }
  .dhs-spend-item { width: 100%; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 10px; padding: 8px 9px; border-radius: 10px; text-align: left; transition: background-color 150ms; animation: dhs-spend-rise 380ms var(--dhs-spend-ease) both; animation-delay: calc(var(--i) * 35ms); }
  .dhs-spend-item:hover { background: color-mix(in oklch, var(--dhs-spend-ink) 4%, transparent); }
  .dhs-spend-item[aria-expanded="true"] { background: color-mix(in oklch, var(--tc) 10%, transparent); box-shadow: inset 3px 0 0 var(--tc); }
  .dhs-spend-item b { font-size: 12.5px; font-weight: 650; line-height: 1.25; }
  .dhs-spend-item small { grid-column: 1; font-size: 10.5px; color: var(--dhs-spend-muted); }
  .dhs-spend-item strong { grid-row: 1; grid-column: 2; text-align: right; font: 650 12px var(--dhs-spend-mono); font-variant-numeric: tabular-nums; }
